const e=[{id:"sv-1-541",phase:1,topic:"1.1.4",qtype:"concept",difficulty:1,stem:"In the book's classification of process inputs, what is a **procedural (P)** input?",options:["An input that can be adjusted while the process runs, such as feed rate","An input that comes from a standard set of activities, such as a set-up routine","An input the team cannot, or chooses not to, control, such as humidity","An output characteristic that is monitored, such as cycle time"],answer:1,hint:"Recall the three input classes C, P and N and what each one means.",steps:[{title:"Key idea",body:"The book (p. 113) tags inputs as **Controllable** (adjusted during the run), **Procedural** (from a standard set of activities) or **Noise** (not controlled)."},{title:"Apply to the stem",body:"A set-up routine, a data-entry form or an escalation checklist is a fixed way of working, so it is a procedural input."},{title:"Eliminate look-alikes",body:"Feed rate is controllable, humidity is noise, and cycle time is a Y, not an input at all."}],final:"Standard set of activities = procedural input → answer **B**",whyWrong:["Incorrect — an input adjusted while the process runs is a controllable (C) input.","","Incorrect — an input that is not controlled is a noise (N) input.","Incorrect — cycle time is an output (Y) that is monitored, not an input."],bookRef:"Book p. 113"},{id:"sv-1-542",phase:1,topic:"1.1.4",qtype:"concept",difficulty:3,stem:"Why does the book warn that **controllable (C)** inputs still need attention?",options:["They are never under complete control, even though they can be adjusted","They cannot be measured until the Control phase of the project","They always have a weaker effect on Y than the noise inputs","They are fixed by procedures and cannot be changed during the run"],answer:0,hint:"Even the inputs the team can adjust do not stay exactly where they are set.",steps:[{title:"Key idea",body:'The book (p. 113) notes that even "controllable" inputs are **never under complete control** — settings drift and people adjust them differently.'},{title:"Apply to the stem",body:"So controllable inputs still need a requirement and a measurement, especially if they are critical X's."},{title:"Eliminate look-alikes",body:"Being fixed by procedures describes procedural inputs; nothing says C inputs are weaker or unmeasurable."}],final:"Controllable does not mean fully controlled → answer **A**",whyWrong:["","Incorrect — controllable inputs can be measured at any time; measurement is planned in Measure, not delayed to Control.","Incorrect — the strength of an input's effect on Y does not depend on its class; that is proven with data.","Incorrect — inputs fixed by a standard set of activities are procedural (P), not controllable."],bookRef:"Book p. 113"},{id:"sv-1-543",phase:1,topic:"1.1.4",qtype:"concept",difficulty:2,stem:"How is a known **noise (N)** input usually handled when it cannot be removed economically?",options:["By adjusting it while the process runs, in the same way as a machine setting","By writing it into the standard work instruction so operators follow it","By making the process robust to it, for example by placing spares before the rainy season","By dropping it from Y = f(X) because only controllable inputs affect Y"],answer:2,hint:"You cannot stop the weather, but you can plan for it.",steps:[{title:"Key idea",body:"Noise inputs are things the team cannot control, does not know about, or finds too costly to control (book p. 113)."},{title:"Apply to the stem",body:"A known noise input is still worth studying: the process is designed to be **robust** to it rather than to control it."},{title:"Eliminate look-alikes",body:"Adjusting during the run is how C inputs are managed; work instructions manage P inputs; noise still affects Y."}],final:"Noise is handled by robustness, not by control → answer **C**",whyWrong:["Incorrect — adjusting an input during the run is how controllable (C) inputs are managed.","Incorrect — work instructions manage procedural (P) inputs; a work instruction cannot change the weather or humidity.","","Incorrect — noise inputs can strongly affect Y; ignoring them leaves variation unexplained."],bookRef:"Book p. 113"},{id:"sv-1-544",phase:1,topic:"1.1.4",qtype:"concept",difficulty:1,stem:"What does the term $\\varepsilon$ represent in $Y = f(X_1, \\ldots, X_n) + \\varepsilon$?",options:["A calculation mistake made by the project team","The target value of Y agreed with the customer","The single most important critical X in the model","The variation in Y that the listed X's do not explain"],answer:3,hint:"The error term is what is left over after the listed inputs.",steps:[{title:"Key idea",body:"The **error term** collects variation in Y from unmeasured factors, measurement noise and chance."},{title:"Apply to the stem",body:"It is the part of Y the listed X's do not explain. It is not a mistake by the team."},{title:"Eliminate look-alikes",body:"The target comes from the VOC, and a critical X is one of the X's inside f."}],final:"Error term = unexplained variation → answer **D**",whyWrong:["Incorrect — the error term is not a team mistake; it is natural unexplained variation.","Incorrect — a target for Y comes from the customer (VOC) and is not part of the equation.","Incorrect — critical X's are inside the function f, not in the error term.",""],trap:"Epsilon is unexplained variation — not an error made by the analyst.",bookRef:"Book p. 526"},{id:"sv-1-545",phase:1,topic:"1.1.4",qtype:"concept",difficulty:2,stem:"In the book's DMAIC funnel, which tools are used mainly in **Measure** to narrow the many X's down to the **probable** X's?",options:["Box plots, scatter plots and regression","Process map, X-Y matrix and FMEA","Fractional and full factorial designs","SIPOC, VOC and project scope"],answer:1,hint:"Each funnel stage has its own tools; Measure prioritises, Analyze proves.",steps:[{title:"Key idea",body:"The book's strategy funnel (pp. 240, 474) runs: SIPOC, VOC, scope → process map, X-Y matrix, FMEA, capability → box plots, scatter plots, regression → factorial designs."},{title:"Apply to the stem",body:"The process map, X-Y matrix and FMEA rank the X's so data collection can focus on the probable ones."},{title:"Eliminate look-alikes",body:"Graphs and regression test X's in Analyze; DOE belongs to Improve; SIPOC and VOC open the project in Define."}],final:"Measure narrows X's with map, X-Y matrix and FMEA → answer **B**",whyWrong:["Incorrect — box plots, scatter plots and regression test the probable X's in Analyze.","","Incorrect — factorial designs sit at the narrow end of the funnel, in Improve.","Incorrect — SIPOC, VOC and scope sit at the wide top of the funnel, in Define."],bookRef:"Book pp. 240, 474"},{id:"sv-1-546",phase:1,topic:"1.1.4",qtype:"concept",difficulty:1,stem:"In the X funnel, what does the term **trivial many** refer to?",options:["The few proven X's that drive most of the change in Y","The large number of possible X's found at the start of a project","The outputs that the Process Owner monitors in Control","The minor defect types left off a Pareto chart"],answer:1,hint:"The funnel is wide at the top and narrow at the bottom.",steps:[{title:"Key idea",body:"At the top of the funnel (book p. 240) process mapping finds all the possible X's — the **trivial many**."},{title:"Apply to the stem",body:"Measure and Analyze then narrow them to the probable and finally the **vital few**."},{title:"Eliminate look-alikes",body:"The proven X's are the vital few; monitored outputs are Y's."}],final:"Trivial many = all the possible X's at the start → answer **B**",whyWrong:["Incorrect — the few proven X's are the vital few at the narrow end of the funnel.","","Incorrect — outputs monitored in Control are Y's, not the candidate X's.","Incorrect — Pareto categories are defect types, not the candidate inputs of the funnel."],bookRef:"Book p. 240"},{id:"sv-1-547",phase:1,topic:"1.1.4",qtype:"concept",difficulty:2,stem:"Which are the book's three main **sources** of candidate X's?",options:["Control charts, control plans and process audits","The project charter, SIPOC and stakeholder analysis","Hypothesis tests, regression and designed experiments","Process mapping, fishbone analysis and basic data analysis"],answer:3,hint:"Where do the ideas for X's come from before anything is proven?",steps:[{title:"Key idea",body:"The book (p. 118) names three main sources of X's: **process mapping, fishbone analysis and basic data analysis**."},{title:"Apply to the stem",body:"These generate the list of candidate inputs at the wide top of the funnel."},{title:"Eliminate look-alikes",body:"Tests, regression and DOE verify X's later; control charts and plans hold X's in Control."}],final:"Map, fishbone, basic data = sources of X's → answer **D**",whyWrong:["Incorrect — control charts, plans and audits hold the vital X's in Control; they do not generate candidates.","Incorrect — the charter, SIPOC and stakeholder analysis scope the project rather than list its X's.","Incorrect — tests, regression and DOE verify X's in Analyze and Improve; they do not generate the list.",""],bookRef:"Book p. 118"},{id:"sv-1-548",phase:1,topic:"1.1.4",qtype:"concept",difficulty:2,stem:"What is the purpose of listing candidate X's during **Define**?",options:["To confirm the root cause before Measure begins","To set the specification limits for the project Y","To record hypotheses that Measure and Analyze will check with data","To assign each X to a process owner for control"],answer:2,hint:"Define lists suspects; it does not convict them.",steps:[{title:"Key idea",body:"In Define the team scopes the Y and may list **potential causes** — opinions and experience, not proof."},{title:"Apply to the stem",body:"The list is a set of hypotheses. Measure gathers reliable data and Analyze tests which X's matter."},{title:"Eliminate look-alikes",body:"Root causes are verified in Analyze; spec limits come from the VOC; control of X's starts in Improve and Control."}],final:"Define X's are hypotheses to be tested → answer **C**",whyWrong:["Incorrect — root causes are verified with data in Analyze, not confirmed in Define.","Incorrect — specification limits come from customer and business requirements, not from a list of X's.","","Incorrect — X's are controlled only after they are proven critical, in Improve and Control."],bookRef:"Book pp. 240, 526"},{id:"sv-1-549",phase:1,topic:"1.1.4",qtype:"concept",difficulty:2,stem:"Which statement about **potential causes** and **root causes** is CORRECT?",options:["A potential cause becomes a root cause only when data show that changing it changes Y","Root causes are confirmed in Define when the Champion approves the charter","Potential causes are first listed in Control so that the control plan can be updated","A root cause is any X named by an experienced process expert"],answer:0,hint:"Opinion versus evidence.",steps:[{title:"Key idea",body:'A **potential cause** is a hypothesis ("we suspect…"). A **root cause** is an X verified with data ("data show that…").'},{title:"Apply to the stem",body:"Verification happens with graphs and statistical tests in Analyze."},{title:"Eliminate look-alikes",body:"Charter approval proves nothing; Control holds proven X's; expert opinion is still only a potential cause."}],final:"Root cause = verified with data → answer **A**",whyWrong:["","Incorrect — Define only lists potential causes; verification with data happens in Analyze.","Incorrect — Control holds already-proven X's; potential causes are listed early, in Define and Measure.","Incorrect — expert opinion produces a potential cause; it becomes a root cause only after data confirm it."],bookRef:"Book p. 240"},{id:"sv-1-550",phase:1,topic:"1.1.4",qtype:"concept",difficulty:2,stem:"Which statement about the number of Y's in a project is CORRECT?",options:["A project should optimise every output of the process together so that no trade-off is missed","The number of Y's in a project should equal the number of critical X's found","Secondary measures should never be tracked once the primary Y is chosen","A project should focus on one primary Y at a time, because optimising several at once is overwhelming"],answer:3,hint:"The book is explicit about trying to optimise more than one Y.",steps:[{title:"Key idea",body:"The book (p. 116) warns that trying to optimise more than one Y at a time becomes overwhelming."},{title:"Apply to the stem",body:"Choose one primary Y; other measures can still be watched so the project does not harm them."},{title:"Eliminate look-alikes",body:"Optimising all outputs is what the book warns against; Y's and X's are not counted to match."}],final:"One primary Y at a time → answer **D**",whyWrong:["Incorrect — optimising every output at once is exactly what the book calls overwhelming.","Incorrect — several X's usually drive one Y; there is no rule that the counts match.","Incorrect — other measures can still be watched so the improvement does not damage them.",""],bookRef:"Book p. 116"},{id:"sv-1-551",phase:1,topic:"1.1.4",qtype:"statements",difficulty:2,stem:`Which statements about input classes are CORRECT?

1. A conveyor speed setting is a controllable input.
2. A set-up checklist is a procedural input.
3. Outdoor humidity is a controllable input.
4. Procedural inputs work well even if nobody is trained on them.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:0,hint:"C = adjusted during the run; P = standard set of activities; N = not controlled.",steps:[{title:"Check each statement",body:"1 is true: speed is adjusted while the process runs. 2 is true: a checklist is a standard set of activities."},{title:"Find the false ones",body:"3 is false: humidity is noise. 4 is false: procedural inputs are controlled through documents **and training**, and only if people follow them."}],final:"Statements 1 and 2 are correct → answer **A**",whyWrong:["","Incorrect — statement 3 is false because humidity is a noise input.","Incorrect — statements 3 and 4 are both false: humidity is noise and procedures need training.","Incorrect — statement 4 is false because procedural inputs depend on training and discipline."],bookRef:"Book p. 113"},{id:"sv-1-552",phase:1,topic:"1.1.4",qtype:"statements",difficulty:3,stem:`Which statements about the X funnel are CORRECT?

1. The X's are first listed in Improve.
2. In Define, process mapping is used to find the possible X's.
3. Analyze tests the probable X's and leaves the vital few.
4. The X-Y matrix proves root causes statistically.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:1,hint:"Wide top in Define, narrowing in Measure, proof in Analyze.",steps:[{title:"Check each statement",body:"2 is true: Define maps the process to find possible X's. 3 is true: Analyze tests them and leaves the vital few."},{title:"Find the false ones",body:"1 is false: X's are listed at the start, not in Improve. 4 is false: the X-Y matrix ranks X's by team judgement; it does not prove anything."}],final:"Statements 2 and 3 are correct → answer **B**",whyWrong:["Incorrect — statement 1 is false because candidate X's are listed at the start, in Define.","","Incorrect — statement 4 is false because an X-Y matrix prioritises X's by judgement; proof comes from data in Analyze.","Incorrect — statements 1 and 4 are both false."],bookRef:"Book pp. 240, 474"},{id:"sv-1-553",phase:1,topic:"1.1.4",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

The book classifies process inputs as controllable, procedural or [?].`,options:["critical","dependent","noise","output"],answer:2,hint:"C, P and …?",steps:[{title:"Key idea",body:"The book (p. 113) uses three input classes: **C**ontrollable, **P**rocedural and **N**oise."},{title:"Eliminate look-alikes",body:"Critical describes an X's importance, not its class; dependent and output describe Y."}],final:"C, P, N = controllable, procedural, noise → answer **C**",whyWrong:["Incorrect — critical describes how strongly an X affects Y, not how much control the team has.","Incorrect — dependent describes the Y, not a class of input.","","Incorrect — an output is a Y; the sentence lists classes of input."],bookRef:"Book p. 113"},{id:"sv-1-554",phase:1,topic:"1.1.4",qtype:"missing-word",difficulty:2,stem:`Identify the missing words in the following sentence.

In the X funnel, Analyze tests the probable X's so that only the [?] remain.`,options:["critical outputs","noise inputs","trivial many","vital few"],answer:3,hint:"The funnel narrows from many to few.",steps:[{title:"Key idea",body:"The funnel (book p. 240) narrows the trivial many X's to the probable X's in Measure and to the **vital few** in Analyze."},{title:"Eliminate look-alikes",body:"The trivial many are at the top of the funnel; outputs are Y's; noise is an input class, not a funnel stage."}],final:"Analyze leaves the vital few → answer **D**",whyWrong:["Incorrect — outputs are Y's; the funnel narrows inputs (X's).","Incorrect — noise is a class of input, not the result of the funnel.","Incorrect — the trivial many are the possible X's at the wide top of the funnel.",""],bookRef:"Book p. 240"},{id:"sv-1-555",phase:1,topic:"1.1.4",qtype:"not-except",difficulty:3,stem:"Which is NOT a usual result of putting pressure on Y alone, without changing any X?",options:["A lasting reduction in the variation of Y","A short-term improvement while people are being watched","Workarounds that hide the problem instead of fixing it","Gaming of the metric, such as reopening tickets to stop the clock"],answer:0,hint:"If no X changes, can Y change for good?",steps:[{title:"Key idea",body:"Y is the scoreboard, not the steering wheel. Without a change in the X's, the process is the same process."},{title:"Apply to the stem",body:"Pressure on Y gives short-term effort, workarounds or gaming, then results drift back."},{title:"Find the outsider",body:"A **lasting** reduction in variation needs a change in the critical X's."}],final:"Lasting improvement needs a change in the X's → answer **A**",whyWrong:["","Incorrect — a short-term gain while people are watched is a typical result of pressure on Y.","Incorrect — workarounds are a typical result when Y is pushed but X's stay the same.","Incorrect — gaming the metric is a typical result of pressure on Y alone."],bookRef:"Book p. 526"},{id:"sv-1-556",phase:1,topic:"1.1.4",qtype:"not-except",difficulty:2,stem:"For a contact-centre call, which input is NOT a **procedural (P)** input?",options:["The call-handling script","The number of agents rostered on the shift","The escalation checklist","The identity-verification routine"],answer:1,hint:"P = a standard set of activities; C = something you can adjust while the process runs.",steps:[{title:"Key idea",body:"Procedural inputs come from a standard set of activities; controllable inputs are adjusted during the run (book p. 113)."},{title:"Apply to the stem",body:"Script, checklist and verification routine are all fixed ways of working — procedural."},{title:"Find the outsider",body:"The number of agents rostered can be changed by the planner from shift to shift: a controllable input."}],final:"Agents rostered is a controllable input → answer **B**",whyWrong:["Incorrect — a call script is a standard set of activities, so it is procedural.","","Incorrect — an escalation checklist is a standard set of activities, so it is procedural.","Incorrect — a verification routine is a standard set of activities, so it is procedural."],bookRef:"Book p. 113"},{id:"sv-1-557",phase:1,topic:"1.1.4",qtype:"scenario",difficulty:2,stem:"After brainstorming, a team has **34** possible X's for late bill delivery. It scores each X against the CTQs in a matrix and keeps **9** for data collection. Which stage of the X funnel has the team reached?",options:["The vital few X's, typically in Analyze","The trivial many X's, typically in Define","The probable X's, typically in Measure","The controlled X's, typically in Control"],answer:2,hint:"Scoring X's in a matrix prioritises them; it does not prove them.",steps:[{title:"Key idea",body:"The funnel goes trivial many (Define) → probable (Measure, using map, X-Y matrix, FMEA) → vital few (Analyze, using data)."},{title:"Apply to the stem",body:"A scoring matrix that cuts 34 X's to 9 is prioritisation by judgement — the probable X's."},{title:"Eliminate look-alikes",body:"The vital few need data and tests; 34 unscored X's would be the trivial many."}],final:"Matrix-scored shortlist = probable X's → answer **C**",whyWrong:["Incorrect — the vital few are proven with data and tests, which this team has not yet done.","Incorrect — the trivial many were the 34 brainstormed X's before scoring.","","Incorrect — X's are controlled only after they are proven and improved."],bookRef:"Book pp. 240, 474"},{id:"sv-1-558",phase:1,topic:"1.1.4",qtype:"scenario",difficulty:3,stem:'In Define, a broadband team agrees that "old routers" cause slow speeds and asks to start a router-swap programme at once. No data on router age versus speed have been collected. What is this an example of?',options:["Controlling a verified critical X","Making the process robust to noise","Solution jumping on a potential cause","Narrowing the X's with an X-Y matrix"],answer:2,hint:"Was the cause proven before the fix was chosen?",steps:[{title:"Key idea",body:"A suspected cause is only a **potential cause** until data verify it. Moving straight to a fix is **solution jumping**."},{title:"Apply to the stem",body:"No data link router age to speed, so the team is fixing a hypothesis."},{title:"Eliminate look-alikes",body:"A verified critical X needs data; robust design deals with noise; an X-Y matrix is a prioritising tool."}],final:"Fixing an unproven cause = solution jumping → answer **C**",whyWrong:["Incorrect — an X is a verified critical X only after data prove it drives Y.","Incorrect — robustness deals with uncontrollable noise inputs; router choice is not noise.","","Incorrect — an X-Y matrix ranks many X's; this team skipped analysis entirely."],trap:"Define lists suspects; Analyze convicts them.",bookRef:"Book p. 240"},{id:"sv-1-559",phase:1,topic:"1.1.4",qtype:"best-action",difficulty:3,stem:"A Black Belt's draft charter for field repair lists **six** project Y's: repair time, first-time fix, cost per job, NPS, safety incidents and fuel use. The Champion asks her to revise it. What is the BEST revision?",options:["Choose one primary Y and keep the others as secondary measures to watch","Keep all six Y's so that no possible improvement is missed","Replace the Y's with the list of suspected X's for repair delays","Remove all Y's until Analyze has proven the root cause"],answer:0,hint:"The book warns about optimising more than one Y.",steps:[{title:"Key idea",body:"Trying to optimise more than one Y at a time is overwhelming (book p. 116)."},{title:"Apply to the stem",body:"Pick the one primary Y that reflects the problem; watch the others so they are not harmed."},{title:"Eliminate look-alikes",body:"Six Y's is the problem itself; X's are not a substitute for a Y; a project needs its Y from Define."}],final:"One primary Y, others watched → answer **A**",whyWrong:["","Incorrect — six Y's at once is what the book calls overwhelming.","Incorrect — X's are inputs to be investigated; the charter still needs the output Y.","Incorrect — the Y is defined in Define; the project cannot measure or analyse without it."],bookRef:"Book p. 116"},{id:"sv-1-560",phase:1,topic:"1.1.4",qtype:"best-action",difficulty:3,stem:"A Black Belt finds that **ambient humidity** strongly affects print defects on bill envelopes. The site cannot control humidity economically, so she drops humidity from her analysis. Was this an appropriate action?",options:["Yes, because only controllable inputs belong in Y = f(X)","Yes, because noise inputs do not affect the output Y","No, because humidity should be reclassified as a procedural input","No, because the process can be made robust to a known noise input"],answer:3,hint:"Noise you cannot control can still be designed around.",steps:[{title:"Key idea",body:"Noise inputs are not controlled, but they still drive Y. Knowing them lets the team make the process **robust**."},{title:"Apply to the stem",body:"Dropping humidity throws away a known driver of defects; she could adapt ink, storage or timing instead."},{title:"Eliminate look-alikes",body:"Y = f(X) includes all inputs; humidity is not a standard activity, so it is not procedural."}],final:"Keep the noise input and design robustness → answer **D**",whyWrong:["Incorrect — Y = f(X) includes controllable, procedural and noise inputs.","Incorrect — the stem says humidity strongly affects defects; noise can drive Y.","Incorrect — procedural inputs come from a standard set of activities; humidity is environmental noise.",""],bookRef:"Book p. 113"},{id:"sv-1-561",phase:1,topic:"1.1.4",qtype:"output",difficulty:3,stem:`A team suspects **crew** (day or night) is a critical X for set-up time (minutes):

\`\`\`
Two-Sample T-Test and CI: SetupTime, Crew
Crew    N   Mean  StDev  SE Mean
Day    30   42.1    6.3      1.2
Night  30   43.0    6.8      1.2

Difference = μ (Day) - μ (Night)
Estimate for difference:  -0.9
95% CI for difference:  (-4.3, 2.5)
T-Test of difference = 0 (vs ≠): T-Value = -0.53  P-Value = 0.597  DF = 57
\`\`\`

At α = 0.05, which conclusion is correct?`,options:["Reject H₀; crew is a critical X and must now be controlled","Reject H₀; crew is a noise input and can be ignored","Fail to reject H₀; crew is proven to have no effect on any output","Fail to reject H₀; crew is not shown to be a critical X for set-up time"],answer:3,hint:"Compare the p-value with α; a candidate X stays in the funnel only if data support it.",steps:[{title:"Read the output",body:"P-Value = 0.597, which is greater than 0.05, and the CI (-4.3, 2.5) includes 0."},{title:"Decide",body:"Fail to reject H₀: the data do not show that crew affects set-up time, so it is not shown to be a critical X."},{title:"Eliminate look-alikes",body:"Rejecting needs p < α; failing to reject never proves 'no effect' on every output."}],final:"p = 0.597 > 0.05 → fail to reject; crew not shown critical → answer **D**",whyWrong:["Incorrect — rejecting H₀ requires p < 0.05; here p = 0.597.","Incorrect — p = 0.597 does not allow rejection, and noise inputs are not simply ignored.","Incorrect — failing to reject is not proof of no effect, and this test only covers set-up time.",""],trap:"'Fail to reject H₀' is not the same as proving H₀.",bookRef:"Book p. 240"},{id:"sv-1-562",phase:1,topic:"1.1.4",qtype:"output",difficulty:3,stem:`A team scores candidate X's for late bill delivery against weighted CTQs:

\`\`\`
X-Y Matrix: Late bill delivery
CTQ (weight)           Accuracy(10)  On-time(7)  Cost(3)  Total
Billing cut-off rule         9            9          3      162
Print vendor capacity        3            9          9      120
Address data quality         9            3          1      114
Envelope colour              1            1          3       26
\`\`\`

Which conclusion is correct?`,options:["Billing cut-off rule is proven to be the root cause of late bills","Billing cut-off rule is the highest-priority probable X for data collection","Envelope colour must be controlled as a critical X","Print vendor capacity should be dropped because its accuracy score is low"],answer:1,hint:"An X-Y matrix ranks X's by team judgement; it does not prove anything.",steps:[{title:"Read the output",body:"Billing cut-off rule has the highest total (162); envelope colour the lowest (26)."},{title:"Decide",body:"The matrix is a Measure-phase prioritising tool, so the top X is the first to collect data on — still a probable X."},{title:"Eliminate look-alikes",body:"Proof needs data in Analyze; a low total argues against control; one low column score does not remove an X with 120."}],final:"Highest total = top probable X, not a proven root cause → answer **B**",whyWrong:["Incorrect — an X-Y matrix is based on team ratings; proof of a root cause needs data in Analyze.","","Incorrect — envelope colour has the lowest total (26), so it is the least likely X.","Incorrect — print vendor capacity has the second-highest total (120) and stays on the shortlist."],trap:"A high X-Y matrix score is a priority, not a proof.",bookRef:"Book pp. 240, 474"},{id:"sv-1-563",phase:1,topic:"1.1.4",qtype:"true-false",difficulty:1,stem:"In the book's funnel, FMEA and the X-Y matrix narrow the many X's to the **probable** X's, which are then tested with data. True or False?",options:["True","False"],answer:0,hint:"Which funnel tools prioritise and which tools prove?",steps:[{title:"Key idea",body:"FMEA and the X-Y matrix sit in Measure and narrow the many X's to the probable X's (book p. 474)."},{title:"Apply to the stem",body:"Proof comes later, in Analyze, from graphs, tests and regression. The statement is true."}],final:"They prioritise; Analyze proves → True → answer **A**",whyWrong:["","Incorrect — FMEA and the X-Y matrix do narrow the X's to probable ones; data then test them in Analyze."],bookRef:"Book pp. 240, 474"},{id:"sv-1-564",phase:1,topic:"1.1.4",qtype:"sequence",difficulty:2,stem:`Put these tool groups in the order they appear in the book's strategy funnel.

- **P** Box plots, scatter plots and regression
- **Q** SIPOC and VOC
- **R** Process map, X-Y matrix and FMEA
- **S** Full factorial designs`,options:["R, Q, P, S","Q, P, R, S","Q, R, P, S","Q, R, S, P"],answer:2,hint:"Scope first, then prioritise, then analyse, then experiment.",steps:[{title:"Key idea",body:"The funnel (book p. 474) runs SIPOC → VOC → scope → map, X-Y matrix, FMEA → graphs and regression → fractional → full factorial."},{title:"Apply to the stem",body:"Q (Define) → R (Measure) → P (Analyze) → S (Improve)."},{title:"Eliminate look-alikes",body:"Each wrong order swaps two neighbouring funnel stages."}],final:"Define → Measure → Analyze → Improve tools: Q, R, P, S → answer **C**",whyWrong:["Incorrect — SIPOC and VOC open the funnel; the process map and X-Y matrix come after them.","Incorrect — graphs and regression test the X's after the X-Y matrix and FMEA have narrowed them.","","Incorrect — full factorial designs come at the narrow end, after regression and graphical analysis."],bookRef:"Book p. 474"},{id:"sv-1-565",phase:1,topic:"1.1.5",qtype:"concept",difficulty:1,stem:"What does the **Voice of the Business (VOB)** describe?",options:["The expressed and unexpressed needs of whoever receives the output","The actual performance and capability of the process","The views of the people who carry out the process every day","The needs of the business and its stakeholders, such as profitability, growth and market share"],answer:3,hint:"Which voice speaks for leaders, finance and regulators?",steps:[{title:"Key idea",body:"The book glossary (p. 590) links VOB to the needs of the business and its key stakeholders: profitability, revenue, growth, market share."},{title:"Eliminate look-alikes",body:"Needs of the output's receiver = VOC; actual performance = VOP; people doing the work = VOE."}],final:"Business needs = VOB → answer **D**",whyWrong:["Incorrect — the needs of whoever receives the output are the Voice of the Customer.","Incorrect — actual process performance and capability is the Voice of the Process.","Incorrect — the views of people who run the process are the Voice of the Employee.",""],bookRef:"Book p. 590"},{id:"sv-1-566",phase:1,topic:"1.1.5",qtype:"concept",difficulty:2,stem:"In process capability analysis, which two voices are compared?",options:["The Voice of the Business with the Voice of the Employee","The Voice of the Process with the Voice of the Customer","The Voice of the Customer with the Voice of the Employee","The Voice of the Business with the Voice of the Process"],answer:1,hint:"Capability asks: can what the process delivers meet what is required?",steps:[{title:"Key idea",body:"The book (p. 208) shows capability as a comparison of the customer's **specification limits** (VOC) with the process spread (VOP)."},{title:"Apply to the stem",body:"The gap between required and delivered is the capability question."},{title:"Eliminate look-alikes",body:"VOB and VOE matter to the project but are not the two sides of a capability study."}],final:"Capability = VOP compared with VOC → answer **B**",whyWrong:["Incorrect — VOB and VOE describe business and staff needs; neither is the process spread or the specification.","","Incorrect — VOE is not part of the capability comparison; the process data (VOP) are.","Incorrect — capability compares the process with customer specifications, not with business goals."],bookRef:"Book p. 208"},{id:"sv-1-567",phase:1,topic:"1.1.5",qtype:"concept",difficulty:1,stem:"Who is a **customer** in Lean Six Sigma terms?",options:["Anyone who uses or consumes the output, inside or outside the organisation","Only an external party who pays for the product or service","The senior manager who sponsors the improvement project","Any employee who performs a step inside the process"],answer:0,hint:"The glossary definition covers more than paying buyers.",steps:[{title:"Key idea",body:"The book glossary (p. 585) defines a customer as anyone who uses or consumes a product or service, internal or external."},{title:"Eliminate look-alikes",body:"Paying buyers are only external customers; the sponsor and the process members are other roles."}],final:"Customer = any user of the output, internal or external → answer **A**",whyWrong:["","Incorrect — this describes only external customers; internal customers also use outputs.","Incorrect — the sponsor directs and funds the work; being a sponsor does not make someone a customer of the output.","Incorrect — people who perform the steps are process members; their view is VOE."],bookRef:"Book p. 585"},{id:"sv-1-568",phase:1,topic:"1.1.5",qtype:"concept",difficulty:2,stem:"Which describes the difference between **reactive** and **proactive** VOC sources?",options:["Reactive sources are always quantitative; proactive sources are always qualitative","Reactive sources come from employees; proactive sources come from customers","Reactive sources are used in Control; proactive sources are used only in Define","Reactive sources arrive whether or not the team asks; proactive sources are designed by the team"],answer:3,hint:"Who starts the conversation: the customer or the team?",steps:[{title:"Key idea",body:"Complaints, escalations and ticket data arrive anyway (**reactive**). Surveys, interviews, focus groups and gemba are planned by the team (**proactive**)."},{title:"Eliminate look-alikes",body:"Both kinds can be qualitative or quantitative, both come from customers, and neither is tied to one phase."}],final:"Reactive = arrives anyway; proactive = designed by the team → answer **D**",whyWrong:["Incorrect — complaints can be text and surveys can be scores; data type does not define reactive versus proactive.","Incorrect — both kinds are customer sources; employee input is the Voice of the Employee.","Incorrect — the difference is who starts the contact, not which DMAIC phase uses it.",""],bookRef:"Syllabus 1.1.5"},{id:"sv-1-569",phase:1,topic:"1.1.5",qtype:"concept",difficulty:2,stem:"What is a purpose of **qualitative** VOC data such as interview comments?",options:["To show how much and how often a problem occurs","To explain what matters to customers and why","To set the control limits for the process","To validate the savings claimed by the project"],answer:1,hint:"Words and stories versus counts and scores.",steps:[{title:"Key idea",body:"Qualitative data (words, stories) tell you **what matters and why**; quantitative data (scores, counts, times) tell you **how much and how often**."},{title:"Eliminate look-alikes",body:"Control limits come from process data (VOP), and savings are validated by Finance."}],final:"Qualitative VOC = what matters and why → answer **B**",whyWrong:["Incorrect — how much and how often is the job of quantitative data such as counts and scores.","","Incorrect — control limits are calculated from process data; they are the Voice of the Process.","Incorrect — savings are validated by the Finance representative, not by customer comments."],bookRef:"Syllabus 1.1.5"},{id:"sv-1-570",phase:1,topic:"1.1.5",qtype:"concept",difficulty:2,stem:"How is a customer verbatim turned into a usable requirement?",options:["By stating the underlying need and then writing a measurable CTQ with a target","By copying the customer's words into the charter as the project goal","By replacing the verbatim with the process's current average performance","By asking the Finance representative to approve the wording"],answer:0,hint:"Verbatim → need → CTQ.",steps:[{title:"Key idea",body:"Customers speak in verbatims; processes need requirements. Translate: verbatim → underlying need → measurable CTQ."},{title:"Apply to the stem",body:'"I waste my day waiting for the technician" → short, reliable window → window ≤ 2 hours, on time in ≥ 95% of visits.'},{title:"Eliminate look-alikes",body:"Raw words are not measurable; current performance is VOP; Finance validates savings, not requirements."}],final:"Verbatim → need → measurable CTQ → answer **A**",whyWrong:["","Incorrect — raw customer words are usually vague and fail the Measurable test of RUMBA.","Incorrect — current performance is the Voice of the Process, not what the customer requires.","Incorrect — Finance validates project savings; it does not write customer requirements."],bookRef:"Book p. 112"},{id:"sv-1-571",phase:1,topic:"1.1.5",qtype:"concept",difficulty:3,stem:"According to the book, what should happen when a process output has **no** requirement or specification?",options:["The Process Owner should set the target equal to current performance","The output should be removed from the process description","The team should ask or negotiate with the customer what is acceptable","The control limits should be used as the specification"],answer:2,hint:"The book calls an output without a requirement 'not acceptable'.",steps:[{title:"Key idea",body:"The book (p. 112) says every output should have a requirement; if one is missing, that is not acceptable and the requirement must be obtained from, or negotiated with, the customer."},{title:"Eliminate look-alikes",body:"Current performance and control limits are VOP, not VOC; deleting the output hides the gap."}],final:"No requirement → negotiate one with the customer → answer **C**",whyWrong:["Incorrect — current performance is the Voice of the Process; it says nothing about what the customer needs.","Incorrect — the output still reaches a customer; removing it from the description hides the problem.","","Incorrect — control limits are VOP and are unrelated to customer specifications."],bookRef:"Book p. 112"},{id:"sv-1-572",phase:1,topic:"1.1.5",qtype:"concept",difficulty:2,stem:"Besides customer requirements, which is a source of specifications listed by the book?",options:["Compliance requirements such as regulations","Control limits calculated from process data","The average of last month's results","The team's brainstormed list of X's"],answer:0,hint:"The book lists customer, business, compliance and design requirements.",steps:[{title:"Key idea",body:"The book (p. 212) lists four sources of specifications: customer (VOC), business, **compliance** and design requirements."},{title:"Eliminate look-alikes",body:"Control limits and past averages describe the process (VOP); X's are candidate causes, not specifications."}],final:"Compliance is one of the four specification sources → answer **A**",whyWrong:["","Incorrect — control limits are the Voice of the Process and are unrelated to specifications.","Incorrect — a past average is performance data (VOP), not a requirement.","Incorrect — a list of X's contains candidate causes, not requirements on the output."],bookRef:"Book p. 212"},{id:"sv-1-573",phase:1,topic:"1.1.5",qtype:"concept",difficulty:2,stem:"What is the main value of capturing the **Voice of the Employee** in Define?",options:["Employees set the specification limits that customers must accept","Employees validate the project's hard and soft savings","Employees who run the process know where it breaks and what blocks them","Employees decide which projects the Champion should select"],answer:2,hint:"The people who patch the process every day.",steps:[{title:"Key idea",body:"VOE covers the people who run the process: workload, tools, training, safety, morale."},{title:"Apply to the stem",body:"They often know exactly where the process breaks because they work around it daily."},{title:"Eliminate look-alikes",body:"Specifications come from customers and the business; savings are Finance's job; project selection is the Champion's."}],final:"VOE = insight from the people doing the work → answer **C**",whyWrong:["Incorrect — specification limits come from customer, business, compliance and design requirements.","Incorrect — the Finance representative validates savings, not the process staff.","","Incorrect — the Champion selects projects in line with business priorities."],bookRef:"Syllabus 1.1.5"},{id:"sv-1-574",phase:1,topic:"1.1.5",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

A valid requirement is Reasonable, Understandable, Measurable, [?] and Achievable.`,options:["Balanced","Believable","Benchmarked","Budgeted"],answer:1,hint:"RUMBA — what is the B?",steps:[{title:"Key idea",body:"RUMBA (book p. 112): **R**easonable, **U**nderstandable, **M**easurable, **B**elievable, **A**chievable."},{title:"Apply to the stem",body:"A requirement must be believable to the people who have to meet it."}],final:"B in RUMBA = Believable → answer **B**",whyWrong:["Incorrect — 'balanced' sounds plausible but is not one of the RUMBA tests.","","Incorrect — benchmarking is a source of business targets, not a RUMBA letter.","Incorrect — budget is a VOB concern, not one of the RUMBA tests."],bookRef:"Book p. 112"},{id:"sv-1-575",phase:1,topic:"1.1.5",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

Capability analysis compares the spread of the process, the Voice of the [?], with the customer's specification limits.`,options:["Business","Customer","Employee","Process"],answer:3,hint:"Specification limits are one voice; process data are the other.",steps:[{title:"Key idea",body:"The spread and centre of the process data are the **Voice of the Process**. Specification limits are the Voice of the Customer."},{title:"Apply to the stem",body:"The sentence already names the customer's limits, so the missing voice is the process."}],final:"Process spread = VOP → answer **D**",whyWrong:["Incorrect — the VOB expresses business needs such as profit and growth, not process spread.","Incorrect — the customer's voice is already in the sentence as the specification limits.","Incorrect — the VOE expresses the needs of staff, not the measured spread of the process.",""],bookRef:"Book p. 208"},{id:"sv-1-576",phase:1,topic:"1.1.5",qtype:"concept",difficulty:2,stem:"Which statement about specification limits and control limits is CORRECT?",options:["Control limits are agreed with the customer in the service contract","Specification limits express the VOC; control limits express the VOP","Specification limits are calculated from ±3 standard deviations of process data","Control limits and specification limits must always be equal"],answer:1,hint:"Which limit comes from the customer and which from the data?",steps:[{title:"Key idea",body:"Specification limits come from the customer (VOC). Control limits are calculated from process data and are **unrelated to specifications** (book p. 525)."},{title:"Eliminate look-alikes",body:"Each wrong option swaps the source of the two kinds of limit or forces them to match."}],final:"Spec limits = VOC; control limits = VOP → answer **B**",whyWrong:["Incorrect — what is agreed in a contract is a specification (VOC); control limits come from data.","","Incorrect — ±3 standard deviations of process data gives control limits, not specification limits.","Incorrect — the two kinds of limit have different sources and are usually different."],bookRef:"Book p. 525"},{id:"sv-1-577",phase:1,topic:"1.1.5",qtype:"concept",difficulty:2,stem:"Which statement about collecting VOC is CORRECT?",options:["Surveys reach only customers who have already complained","Interviews give mainly quantitative data on how often problems occur","Gemba visits are a reactive source of customer data","Complaint data are cheap to obtain but biased towards upset customers"],answer:3,hint:"Reactive versus proactive; qualitative versus quantitative.",steps:[{title:"Key idea",body:"Reactive sources such as complaints arrive anyway, so they are cheap — but they over-represent unhappy customers."},{title:"Eliminate look-alikes",body:"Surveys are proactive and reach quiet customers; interviews give mostly qualitative data; gemba is proactive."}],final:"Complaints = cheap but biased → answer **D**",whyWrong:["Incorrect — surveys are proactive and are designed to reach customers who have not complained.","Incorrect — interviews mainly give qualitative data: what matters and why.","Incorrect — going to where the work is done is planned by the team, so it is proactive.",""],bookRef:"Syllabus 1.1.5"},{id:"sv-1-578",phase:1,topic:"1.1.5",qtype:"concept",difficulty:3,stem:"Which statement about conflicting voices in Define is CORRECT?",options:["The VOC always overrides the VOB and the VOE","The VOB always overrides the VOC because the business funds the project","Trade-offs between VOC, VOB and VOE should be made explicit, for example in the charter","Conflicting voices mean the project should be stopped"],answer:2,hint:"Do not just pick a winner.",steps:[{title:"Key idea",body:"Voices often conflict (24/7 human support vs 10% lower cost vs no extra night shifts)."},{title:"Apply to the stem",body:"Find the real need, segment customers, check with data, design for the shared core and record the trade-offs in the charter."},{title:"Eliminate look-alikes",body:"No voice automatically wins, and conflict is normal, not a reason to stop."}],final:"Make trade-offs explicit → answer **C**",whyWrong:["Incorrect — ignoring business and employee needs produces solutions that cannot be funded or run.","Incorrect — ignoring the customer produces a cheaper process that nobody wants.","","Incorrect — conflict between voices is normal; the team resolves it with data and explicit trade-offs."],bookRef:"Syllabus 1.1.5"},{id:"sv-1-579",phase:1,topic:"1.1.5",qtype:"statements",difficulty:3,stem:`Which statements correctly classify these Define-phase inputs?

1. "The regulator requires call recordings to be kept for 12 months" is VOB.
2. "Night-shift agents say the knowledge-base search times out" is VOE.
3. "A survey shows 41% of callers want a callback option" is VOP.
4. "Average speed of answer last month was 74 seconds" is VOC.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:0,hint:"Business and compliance = VOB; staff = VOE; customer wants = VOC; measured performance = VOP.",steps:[{title:"Check each statement",body:"1 is true: compliance is a business requirement (VOB). 2 is true: staff describing their tools is VOE."},{title:"Find the false ones",body:"3 is false: what callers want is VOC. 4 is false: a measured result of the process is VOP."}],final:"Statements 1 and 2 are correct → answer **A**",whyWrong:["","Incorrect — statement 3 is false because what callers want is the Voice of the Customer.","Incorrect — statements 3 and 4 swap VOC and VOP, so both are false.","Incorrect — statement 4 is false because a measured average is the Voice of the Process."],bookRef:"Book p. 590"},{id:"sv-1-580",phase:1,topic:"1.1.5",qtype:"statements",difficulty:3,stem:`Which statements about RUMBA are CORRECT?

1. "Fast service" passes the Measurable test.
2. RUMBA also applies to requirements placed on suppliers.
3. A requirement that fails a RUMBA test must be negotiated.
4. RUMBA is used to calculate process capability.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:1,hint:"RUMBA checks whether a requirement is valid.",steps:[{title:"Check each statement",body:"2 is true: the book (p. 113) applies the same rules to supplier requirements. 3 is true: a requirement that fails any letter is not valid and must be negotiated."},{title:"Find the false ones",body:'1 is false: "fast" has no measure or target. 4 is false: RUMBA is a requirement check, not a capability calculation.'}],final:"Statements 2 and 3 are correct → answer **B**",whyWrong:["Incorrect — statement 1 is false because 'fast service' has no unit or target.","","Incorrect — statement 4 is false because RUMBA does not calculate capability.","Incorrect — statements 1 and 4 are both false."],bookRef:"Book pp. 112–113"},{id:"sv-1-581",phase:1,topic:"1.1.5",qtype:"not-except",difficulty:1,stem:"Which is NOT normally part of the **Voice of the Business**?",options:["Profitability targets for the year","Market-share goals for a product","Regulatory compliance requirements","Agents' complaints about slow tools"],answer:3,hint:"Who is speaking in each option?",steps:[{title:"Key idea",body:"VOB = business and stakeholder needs: profit, revenue, growth, market share, cost, compliance."},{title:"Find the outsider",body:"Complaints from the agents who run the process are the Voice of the Employee."}],final:"Staff complaints = VOE, not VOB → answer **D**",whyWrong:["Incorrect — profitability is a core VOB need.","Incorrect — market share is named in the book's VOB definition.","Incorrect — compliance with regulations is a business requirement (VOB).",""],bookRef:"Book p. 590"},{id:"sv-1-582",phase:1,topic:"1.1.5",qtype:"not-except",difficulty:1,stem:"Which is NOT a proactive VOC method?",options:["Focus groups with small-business customers","Analysis of the complaint log","One-to-one customer interviews","Gemba visits to customer sites"],answer:1,hint:"Proactive = the team designs and starts the contact.",steps:[{title:"Key idea",body:"Proactive methods are planned by the team: surveys, interviews, focus groups, gemba."},{title:"Find the outsider",body:"Complaints arrive whether the team asks or not, so the complaint log is a **reactive** source."}],final:"Complaint log = reactive → answer **B**",whyWrong:["Incorrect — focus groups are planned by the team, so they are proactive.","","Incorrect — interviews are planned by the team, so they are proactive.","Incorrect — gemba visits are planned by the team, so they are proactive."],bookRef:"Syllabus 1.1.5"},{id:"sv-1-583",phase:1,topic:"1.1.5",qtype:"scenario",difficulty:1,stem:"A service desk dispatches tickets to the field-engineering team. The engineers complain that tickets often arrive without site-access details. What are the field engineers to the service desk?",options:["Internal customers","External customers","Suppliers","Process owners"],answer:0,hint:"Who receives the desk's output?",steps:[{title:"Key idea",body:"A customer is anyone who uses the output (book p. 585). An internal customer is inside the company and depends on that output."},{title:"Apply to the stem",body:"The engineers receive the desk's tickets to do their own job, so they are internal customers of the desk."},{title:"Eliminate look-alikes",body:"They are inside the company (not external) and receive rather than provide the ticket."}],final:"Receives the output, inside the company = internal customer → answer **A**",whyWrong:["","Incorrect — external customers are outside the organisation.","Incorrect — a supplier provides inputs; the engineers receive the desk's output.","Incorrect — a process owner is accountable for a process end to end, not a receiver of its output."],bookRef:"Book p. 585"},{id:"sv-1-584",phase:1,topic:"1.1.5",qtype:"scenario",difficulty:2,stem:'Enterprise customers say: *"We want our invoices to be right first time."* Which is the BEST requirement to take forward from this statement?',options:["Invoices should be much better than they are today","The billing team should try harder every month","The number of invoices printed per day","At least 99.5% of invoice lines correct, with no dispute raised within 30 days"],answer:3,hint:"A requirement must pass RUMBA, especially Measurable.",steps:[{title:"Key idea",body:"Translate the verbatim into a need (accurate bills) and then a measurable CTQ with a target."},{title:"Apply to the stem",body:"Only the first option has a unit, a target and a time frame."},{title:"Eliminate look-alikes",body:"'Much better' and 'try harder' are not measurable; invoices printed is an output count, not accuracy."}],final:"Measurable target = valid requirement → answer **D**",whyWrong:["Incorrect — 'much better' has no measure or target, so it fails RUMBA.","Incorrect — effort is not a requirement on the output and cannot be measured objectively.","Incorrect — a count of invoices printed measures volume, not whether the bill is right.",""],bookRef:"Book p. 112"},{id:"sv-1-585",phase:1,topic:"1.1.5",qtype:"scenario",difficulty:3,stem:'A regional sales director tells the Black Belt: *"Enterprise churn must fall by 2 points so we hit the revenue plan."* Which voice is this?',options:["Voice of the Business","Voice of the Customer","Voice of the Employee","Voice of the Process"],answer:0,hint:"Look at what is being asked for, not who is speaking.",steps:[{title:"Key idea",body:"VOB = profit, revenue, growth, market share, cost, compliance."},{title:"Apply to the stem",body:"The aim is the revenue plan, so this is the business speaking, even though the speaker works with customers."},{title:"Eliminate look-alikes",body:"It is not a customer need, a staff concern or measured process data."}],final:"Revenue target = VOB → answer **A**",whyWrong:["","Incorrect — the statement is about revenue for the company, not what customers need.","Incorrect — the director is not describing the work or tools of process staff.","Incorrect — VOP would be measured churn data, not a target."],trap:"A customer-facing manager can still speak with the Voice of the Business.",bookRef:"Book p. 590"},{id:"sv-1-586",phase:1,topic:"1.1.5",qtype:"scenario",difficulty:2,stem:'A customer says: *"I want the technician to arrive when promised."* The contract sets a 2-hour window. Data show **22%** of visits start more than an hour after the window. Which item is the Voice of the Process?',options:["The 22% late-start figure from visit data","The customer's wish for on-time arrival","The 2-hour window in the contract","The technicians' request for better routing"],answer:0,hint:"VOP is what the process actually delivers.",steps:[{title:"Key idea",body:"VOP = actual performance shown by data. VOC = what is required."},{title:"Apply to the stem",body:"The 22% figure is measured performance, so it is the VOP."},{title:"Eliminate look-alikes",body:"The wish and the contract window are customer requirements; the routing request is VOE."}],final:"Measured result = VOP → answer **A**",whyWrong:["","Incorrect — the customer's wish is the Voice of the Customer.","Incorrect — a contracted window is a customer requirement (VOC), not performance.","Incorrect — a request from technicians is the Voice of the Employee."],bookRef:"Book p. 590"},{id:"sv-1-587",phase:1,topic:"1.1.5",qtype:"best-action",difficulty:2,stem:"A Black Belt must understand what small-business customers need from a new fibre bundle. The product manager says he already knows what they want. What is the BEST first action?",options:["Use the product manager's list as the Voice of the Customer","Collect the customers' voice directly through interviews or surveys","Set the requirements equal to the current process performance","Wait for complaints after launch and then adjust the bundle"],answer:1,hint:"VOC comes from the customer, not from an assumption.",steps:[{title:"Key idea",body:"The VOC is captured from the receivers of the output, using several listening methods."},{title:"Apply to the stem",body:"The product manager's view is a useful hypothesis, but it must be checked with customers."},{title:"Eliminate look-alikes",body:"Current performance is VOP; waiting for complaints is reactive and too late."}],final:"Hear the customer directly → answer **B**",whyWrong:["Incorrect — an internal opinion about customers is an assumption, not the customer's voice.","","Incorrect — current performance is the Voice of the Process, not what customers need.","Incorrect — complaints after launch are reactive and arrive after the design is fixed."],bookRef:"Syllabus 1.1.5"},{id:"sv-1-588",phase:1,topic:"1.1.5",qtype:"best-action",difficulty:3,stem:'The Champion hands a Black Belt the requirement *"Customers want quick repairs"* and asks her to start measuring. She first works with customers to define it as *"repair completed within 8 hours of report in 95% of cases"*. Was this an appropriate action?',options:["Yes, because a requirement must be measurable and understandable before data are collected","Yes, because the Champion's wording is the Voice of the Business","No, because the Champion's words are already a valid Voice of the Customer","No, because requirements are defined only in the Control phase"],answer:0,hint:"Test the requirement with RUMBA.",steps:[{title:"Key idea",body:"A requirement must pass RUMBA: Reasonable, Understandable, Measurable, Believable, Achievable."},{title:"Apply to the stem",body:'"Quick" fails Measurable and Understandable, so negotiating a measurable version with customers is right.'},{title:"Eliminate look-alikes",body:"The wording is about customers, not business needs, and requirements are set early, not in Control."}],final:"Make it measurable first → answer **A**",whyWrong:["","Incorrect — the statement is about what customers want, so it is not the Voice of the Business.","Incorrect — 'quick repairs' fails the Measurable test, so it is not yet a valid requirement.","Incorrect — requirements are captured and validated in Define, long before Control."],bookRef:"Book p. 112"},{id:"sv-1-589",phase:1,topic:"1.1.5",qtype:"output",difficulty:3,stem:`An enterprise contract says faults must be restored within **4 hours**. The Black Belt runs:

\`\`\`
Process Capability Report: Restore time (h)
USL                 4.00
Target              *
Sample Mean         3.10
Sample N            240
StDev(Overall)      1.05
Observed % > USL    18.33
\`\`\`

Which statement correctly links this output to the voices?`,options:["The USL is the VOP; the 18.33% beyond the USL is the VOC","Both the USL and the mean are VOB because they appear in a contract","The USL is the VOC; the mean, spread and 18.33% beyond the USL describe the VOP","The StDev is the VOC because customers feel the variation"],answer:2,hint:"Requirement versus delivered performance.",steps:[{title:"Read the output",body:"USL = 4.00 h comes from the contract. Mean 3.10, StDev 1.05 and 18.33% above the USL come from 240 measured faults."},{title:"Decide",body:"The requirement is the VOC; the measured results are the VOP. Capability compares them."},{title:"Eliminate look-alikes",body:"Swapping the two voices, or calling them VOB, breaks the rule spec = VOC, data = VOP."}],final:"Spec = VOC; measured results = VOP → answer **C**",whyWrong:["Incorrect — this swaps them: the USL is the customer's requirement and the 18.33% is measured performance.","Incorrect — the USL is a customer requirement and the mean is measured performance; neither is a business goal.","","Incorrect — the standard deviation is calculated from process data, so it is VOP."],bookRef:"Book p. 208"},{id:"sv-1-590",phase:1,topic:"1.1.5",qtype:"output",difficulty:3,stem:`A broadband team codes customer comments by theme and by source:

\`\`\`
Tabulated Statistics: Theme, Source
                 Complaint  Survey  Interview  All
Billing error         64       21          9    94
Slow repair           41       38         15    94
Unclear tariff         6       44         27    77
All                  111      103         51   265
\`\`\`

Which conclusion about **Unclear tariff** is correct?`,options:["It would be largely missed if the team relied on complaint data alone","It is the most frequent theme in the complaint data","It is Voice of the Business because it relates to pricing","It can be ignored because only 6 complaints mention it"],answer:0,hint:"Reactive sources over-represent some needs and hide others.",steps:[{title:"Read the output",body:"Unclear tariff: 6 complaints but 44 survey and 27 interview mentions (77 in all)."},{title:"Decide",body:"The need shows up mainly in proactive sources, so a complaints-only view would almost miss it."},{title:"Eliminate look-alikes",body:"Billing error leads the complaints (64); a customer's confusion is VOC; 77 mentions in all is not trivial."}],final:"Hidden from complaints, visible in proactive VOC → answer **A**",whyWrong:["","Incorrect — billing error has the most complaints (64); unclear tariff has only 6.","Incorrect — customers saying the tariff is unclear is a customer need (VOC), even though it involves price.","Incorrect — the theme has 77 mentions in all; complaint counts alone understate it."],trap:"Complaints are only the customers who speak up.",bookRef:"Syllabus 1.1.5"},{id:"sv-1-591",phase:1,topic:"1.1.5",qtype:"true-false",difficulty:1,stem:"A customer can only be an external party who pays for the product or service. True or False?",options:["True","False"],answer:1,hint:"Recall the glossary definition of customer.",steps:[{title:"Key idea",body:"A customer is anyone who uses or consumes a product or service, **inside or outside** the organisation (book p. 585)."},{title:"Apply to the stem",body:"Billing receiving order data from provisioning is an internal customer. The statement is false."}],final:"Customers can be internal → False → answer **B**",whyWrong:["Incorrect — internal teams that use an output are customers too.",""],bookRef:"Book p. 585"},{id:"sv-1-592",phase:1,topic:"1.1.5",qtype:"true-false",difficulty:1,stem:"When field staff report that their workload has become unsafe, the Black Belt should record this as Voice of the Employee alongside the VOC and VOB. True or False?",options:["True","False"],answer:0,hint:"Which voice covers workload, tools, training, safety and morale?",steps:[{title:"Key idea",body:"VOE is the voice of the people who run the process: workload, tools, training, safety, morale."},{title:"Apply to the stem",body:"An unsafe workload is exactly a VOE concern, and it belongs with the other voices in Define. The statement is true."}],final:"Staff safety concern = VOE → True → answer **A**",whyWrong:["","Incorrect — workload and safety concerns from the people doing the work are VOE and should be recorded."],bookRef:"Syllabus 1.1.5"},{id:"sv-1-593",phase:1,topic:"1.1.5",qtype:"sequence",difficulty:2,stem:`Put these steps in order when turning the customer's voice into a requirement.

- **P** Write the CTQ with a target and limits
- **Q** Collect customer verbatims
- **R** Identify the underlying need
- **S** Check the CTQ with RUMBA`,options:["R, Q, P, S","Q, R, P, S","Q, P, R, S","Q, R, S, P"],answer:1,hint:"Words → need → CTQ → check.",steps:[{title:"Key idea",body:"Verbatim → need → CTQ, then test the CTQ with RUMBA."},{title:"Apply to the stem",body:"Q (verbatims) → R (need) → P (CTQ) → S (RUMBA check)."},{title:"Eliminate look-alikes",body:"You cannot find the need before hearing the customer, or check a CTQ before it is written."}],final:"Q, R, P, S → answer **B**",whyWrong:["Incorrect — the need is found from the verbatims, so collecting them comes first.","","Incorrect — the CTQ is written from the underlying need, so the need must come before it.","Incorrect — RUMBA checks a written CTQ, so the CTQ must exist before the check."],bookRef:"Book p. 112"},{id:"sv-1-594",phase:1,topic:"1.1.6",qtype:"concept",difficulty:1,stem:"Which role **recognises, defines, assigns and supports** Six Sigma projects and is accountable for their results?",options:["Master Black Belt","Black Belt","Champion","Process Owner"],answer:2,hint:"Recall the glossary wording for the leadership role closest to projects.",steps:[{title:"Key idea",body:"The book glossary (p. 584) describes the **Champion** as the person who recognises, defines, assigns and supports projects and is accountable for their results."},{title:"Eliminate look-alikes",body:"The MBB coaches, the Black Belt leads, the Process Owner sustains the process."}],final:"Recognise, define, assign, support = Champion → answer **C**",whyWrong:["Incorrect — the Master Black Belt is the technical expert who teaches and mentors Belts.","Incorrect — the Black Belt leads projects under the direction of a Champion.","","Incorrect — the Process Owner is accountable for process performance and sustaining solutions."],bookRef:"Book p. 584"},{id:"sv-1-595",phase:1,topic:"1.1.6",qtype:"concept",difficulty:1,stem:"According to the book, about how long is the training for a **Green Belt**?",options:["About 1 week","About 2 weeks","About 4 weeks","About 8 weeks"],answer:1,hint:"Yellow, Green and Black Belt training lengths roughly double each step.",steps:[{title:"Key idea",body:"The book glossary gives indicative training: Yellow Belt about 1 week, Green Belt about 2 weeks, Black Belt about 4 weeks."},{title:"Apply to the stem",body:"A Black Belt trains for about 2 weeks."}],final:"Green Belt ≈ 2 weeks → answer **B**",whyWrong:["Incorrect — about 1 week is the Yellow Belt.","","Incorrect — about 4 weeks is the Black Belt.","Incorrect — 8 weeks is not a belt duration in the book; the MBB is described as beyond Black Belt."],bookRef:"Book pp. 584–590"},{id:"sv-1-596",phase:1,topic:"1.1.6",qtype:"concept",difficulty:2,stem:"How many training hours does the syllabus recommend for a **Green Belt**?",options:["16 hours","40 hours","80 hours","120 hours"],answer:2,hint:"Syllabus guidance: Yellow 16, Green 80, Black 120.",steps:[{title:"Key idea",body:"The syllabus recommends about **16** hours for Yellow Belt, **80** for Green Belt and **120** for Black Belt."},{title:"Apply to the stem",body:"Green Belt = 80 hours, which matches about 2 weeks of training."}],final:"Green Belt = 80 hours → answer **C**",whyWrong:["Incorrect — 16 hours is the Yellow Belt recommendation.","Incorrect — 40 hours is not one of the syllabus recommendations.","","Incorrect — 120 hours is the Black Belt recommendation."],bookRef:"Syllabus 1.1.6"},{id:"sv-1-597",phase:1,topic:"1.1.6",qtype:"concept",difficulty:2,stem:"Why does the book stress engaging the **Process Owner** early in a project?",options:["The owner must calculate the project's financial savings","The owner must choose the statistical tools for Analyze","The owner must replace the Champion at the tollgate reviews","The owner must keep the solution working long after the Belt moves on"],answer:3,hint:"A Belt leads for months; the process runs for years.",steps:[{title:"Key idea",body:"The Process Owner is responsible for process performance and resources and accountable for implementing solutions (book p. 588)."},{title:"Apply to the stem",body:"In Control the control plan is handed to the owner (p. 578). If the owner is not committed, the gain fades."},{title:"Eliminate look-alikes",body:"Savings belong to Finance, tool choice to the Belt and MBB, tollgates to the Champion."}],final:"The owner sustains the gain → answer **D**",whyWrong:["Incorrect — the Finance representative evaluates the hard and soft savings.","Incorrect — tool selection is the Belt's work, coached by the Master Black Belt.","Incorrect — the Champion chairs tollgate reviews; the owner supports them.",""],bookRef:"Book pp. 578, 588"},{id:"sv-1-598",phase:1,topic:"1.1.6",qtype:"concept",difficulty:2,stem:"Which role normally chairs the **tollgate reviews** and decides whether a project goes on, recycles or stops?",options:["Finance representative","Master Black Belt","Champion","Green Belt"],answer:2,hint:"Who is accountable for the project's results?",steps:[{title:"Key idea",body:"The Champion selects, supports and is accountable for projects, so the Champion chairs the tollgates and makes the go, recycle or stop decision."},{title:"Eliminate look-alikes",body:"Finance checks savings, the MBB advises on method, the Black Belt presents the work."}],final:"Tollgate decision = Champion → answer **C**",whyWrong:["Incorrect — Finance validates savings and may attend, but does not own the go or stop decision.","Incorrect — the MBB advises on rigour; the Champion is accountable for the decision.","","Incorrect — the Black Belt presents the evidence at the tollgate; it does not judge its own project."],bookRef:"Book p. 584"},{id:"sv-1-599",phase:1,topic:"1.1.6",qtype:"concept",difficulty:2,stem:"On the book's DMAIC roadmap, who carries out the first step, **identify the problem area**?",options:["The Black Belt working alone","The Champion or Process Owner","The Finance representative","The Yellow Belt team members"],answer:1,hint:"Problem areas are found by those who own business results and processes.",steps:[{title:"Key idea",body:"The book's roadmap (p. 230) assigns the first step, identify problem area, to the **Champion / Process Owner**."},{title:"Apply to the stem",body:"They see the business priorities and the process performance, so they spot where a project is needed."},{title:"Eliminate look-alikes",body:"Belts and team members are assigned after the problem area is chosen; Finance validates savings later."}],final:"Identify problem area = Champion / Process Owner → answer **B**",whyWrong:["Incorrect — the Belt is assigned to a problem area after it has been identified.","","Incorrect — Finance evaluates savings; it does not identify problem areas.","Incorrect — Yellow Belts join the team once the project exists."],bookRef:"Book p. 230"},{id:"sv-1-600",phase:1,topic:"1.1.6",qtype:"concept",difficulty:1,stem:"Which describes the main role of a **Yellow Belt**?",options:["A part-time leader of smaller projects in their own work area","A full-time leader of larger projects under a Champion","An expert who teaches and mentors the other Belts","A team member on Green and Black Belt projects who applies ideas in their own area"],answer:3,hint:"About one week of training.",steps:[{title:"Key idea",body:"The Yellow Belt (about 1 week of training) is a team member on Green and Black Belt projects."},{title:"Eliminate look-alikes",body:"Part-time leader = Green Belt; full-time leader = Black Belt; teacher and mentor = Master Black Belt."}],final:"Team member = Yellow Belt → answer **D**",whyWrong:["Incorrect — a part-time leader of smaller projects is a Black Belt.","Incorrect — a full-time leader under a Champion is a Black Belt.","Incorrect — the teacher and mentor of Belts is the Master Black Belt.",""],bookRef:"Book p. 590"},{id:"sv-1-601",phase:1,topic:"1.1.6",qtype:"concept",difficulty:1,stem:"What does the **Executive Sponsor** mainly do?",options:["Links the programme to strategy, sets priorities and provides resources","Leads the DMAIC work on a single project","Validates the savings claimed by each project","Collects the data and maps the process"],answer:0,hint:"The most senior role: direction and funding.",steps:[{title:"Key idea",body:"The Executive Sponsor is a senior leader who sets direction, gives resources and visible support, and reviews results across projects."},{title:"Eliminate look-alikes",body:"Belts lead DMAIC, Finance validates savings, team members collect data."}],final:"Sponsor = strategy, priorities, resources → answer **A**",whyWrong:["","Incorrect — leading DMAIC on a project is the Belt's job.","Incorrect — validating savings is the Finance representative's job.","Incorrect — data collection and mapping are done by the team, often Yellow Belts."],bookRef:"Syllabus 1.1.6"},{id:"sv-1-602",phase:1,topic:"1.1.6",qtype:"concept",difficulty:1,stem:"Who normally approves the **project charter** and the project team?",options:["Champion","Process Member","Master Black Belt","Finance representative"],answer:0,hint:"The role that selects and assigns the project.",steps:[{title:"Key idea",body:"The Champion selects and scopes projects, approves the charter and the team, and removes barriers."},{title:"Eliminate look-alikes",body:"Process members do the work; the MBB reviews method; Finance reviews the savings estimate."}],final:"Charter approval = Champion → answer **A**",whyWrong:["","Incorrect — a process member performs activities in the process and may join the team.","Incorrect — the MBB may review the charter for rigour but does not approve it.","Incorrect — Finance reviews the benefit estimate but does not approve the charter or team."],bookRef:"Book p. 584"},{id:"sv-1-603",phase:1,topic:"1.1.6",qtype:"concept",difficulty:3,stem:"Which role **advises** on project selection but does not itself select and assign projects?",options:["Champion","Executive Sponsor","Process Owner","Master Black Belt"],answer:3,hint:"Advising versus deciding.",steps:[{title:"Key idea",body:"The MBB supports Champions with technical advice, including on project selection. The **Champion** selects and assigns projects."},{title:"Apply to the stem",body:"The role that advises without deciding is the MBB."},{title:"Eliminate look-alikes",body:"The Sponsor sets priorities; the Process Owner identifies problem areas with the Champion."}],final:"Advises on selection = MBB → answer **D**",whyWrong:["Incorrect — the Champion is the role that actually selects and assigns projects.","Incorrect — the Sponsor sets strategic priorities across the programme rather than advising on single projects.","Incorrect — the Process Owner helps identify problem areas and sustains solutions.",""],trap:"MBB advises; Champion decides.",bookRef:"Book p. 586"},{id:"sv-1-604",phase:1,topic:"1.1.6",qtype:"concept",difficulty:2,stem:"How does a Black Belt usually support a Black Belt project?",options:["By approving the Black Belt's charter and removing barriers","By working part-time on it, for example on data collection and analysis in their area","By independently validating the Black Belt's savings","By taking ownership of the process after handover"],answer:1,hint:"Green Belts lead smaller projects and support Black Belts.",steps:[{title:"Key idea",body:"A Black Belt works part-time on improvement, leads smaller local projects, and **supports** Black Belt projects."},{title:"Eliminate look-alikes",body:"Approving and unblocking = Champion; savings = Finance; ownership after handover = Process Owner."}],final:"Part-time support with data and analysis → answer **B**",whyWrong:["Incorrect — approving the charter and removing barriers is the Champion's role.","","Incorrect — independent evaluation of savings is the Finance representative's role.","Incorrect — the Process Owner takes over the process after handover."],bookRef:"Book p. 586"},{id:"sv-1-605",phase:1,topic:"1.1.6",qtype:"concept",difficulty:2,stem:"Which group must be identified and kept informed even when its members are **not** on the project team?",options:["Only the Belts who lead the project","Only the Finance representative and the Champion","Stakeholders such as IT, HR, the vendor and regulators","Only the team members who collect data"],answer:2,hint:"Anyone affected by, or able to affect, the project.",steps:[{title:"Key idea",body:"Stakeholders are anyone affected by, or able to affect, the project. Not all are on the team, but all must be identified and kept informed."},{title:"Eliminate look-alikes",body:"Each wrong option names only a small part of the people who matter to the project."}],final:"Stakeholders, on or off the team → answer **C**",whyWrong:["Incorrect — Belts lead the work, but many affected people are not Belts.","Incorrect — Finance and the Champion are only two of the stakeholders.","","Incorrect — data collectors are team members; stakeholders include people outside the team."],bookRef:"Syllabus 1.1.6"},{id:"sv-1-606",phase:1,topic:"1.1.6",qtype:"concept",difficulty:1,stem:"Which statement about the Black Belt and Green Belt roles is CORRECT?",options:["A Black Belt usually works full-time on improvement; a Black Belt works part-time","A Black Belt usually coaches Black Belts on statistical methods","Both roles normally receive the same length of training","A Black Belt leads only small projects in their own work area"],answer:0,hint:"Full-time versus part-time is a favourite distractor.",steps:[{title:"Key idea",body:"Black Belt: about 4 weeks of training, full-time, larger projects under a Champion. Green Belt: about 2 weeks, part-time, smaller local projects."},{title:"Eliminate look-alikes",body:"Coaching runs from Black Belt to Green Belt, not the reverse, and training lengths differ."}],final:"BB full-time, GB part-time → answer **A**",whyWrong:["","Incorrect — Black Belts coach Green Belts, and MBBs coach both.","Incorrect — Black Belts train for about 4 weeks and Green Belts for about 2.","Incorrect — small local projects are typical for Green Belts; Black Belts lead larger ones."],bookRef:"Book pp. 584–590"},{id:"sv-1-607",phase:1,topic:"1.1.6",qtype:"concept",difficulty:2,stem:"Which statement about the **Process Owner** and a **Process Member** is CORRECT?",options:["The owner performs the daily activities; members are accountable for results","Both roles exist only for the duration of the project","A Process Member validates the project savings with Finance","Members perform the work; the owner is accountable for the process end to end"],answer:3,hint:"Doing the work versus being accountable for it.",steps:[{title:"Key idea",body:"A **Process Member** performs activities in the process; the **Process Owner** is responsible for process performance and resources (book p. 588)."},{title:"Eliminate look-alikes",body:"The roles are not reversed, both belong to the process (not the project), and savings are Finance's job."}],final:"Members do; owner is accountable → answer **D**",whyWrong:["Incorrect — this reverses the two roles.","Incorrect — both roles belong to the process and continue after the project closes.","Incorrect — savings are evaluated by the Finance representative.",""],bookRef:"Book p. 588"},{id:"sv-1-608",phase:1,topic:"1.1.6",qtype:"concept",difficulty:2,stem:"According to the book's Control checklist, which statement about **project closure** is CORRECT?",options:["The Belt alone decides when the project is complete","The project closes as soon as the solution has been piloted","The Champion, the Belt and Finance should all agree that the project is complete","Only the Master Black Belt can sign off a completed project"],answer:2,hint:"Three parties agree at the end.",steps:[{title:"Key idea",body:"The book's Control checklist (p. 578) asks whether the Champion, the Belt and Finance all agree the project is complete."},{title:"Eliminate look-alikes",body:"No single role closes the project alone, and a pilot is not the end of Control."}],final:"Champion + Belt + Finance agree → answer **C**",whyWrong:["Incorrect — the Belt cannot close its own project without the Champion and Finance.","Incorrect — after a pilot the solution still needs full implementation and a control plan handover.","","Incorrect — the MBB coaches; closure is agreed by the Champion, the Belt and Finance."],bookRef:"Book p. 578"},{id:"sv-1-609",phase:1,topic:"1.1.6",qtype:"concept",difficulty:2,stem:"Which statement about the **Champion** is CORRECT?",options:["The Champion carries out the statistical analysis for the team","The Champion is accountable for project results even though the Belt leads the work","The Champion takes over process ownership after the project closes","The Champion is normally a Yellow Belt team member"],answer:1,hint:"Accountable versus doing.",steps:[{title:"Key idea",body:"The Champion recognises, defines, assigns and supports projects and is **accountable for their results** (book p. 584)."},{title:"Eliminate look-alikes",body:"Analysis is done by the Belt; ownership after closure is the Process Owner's; Yellow Belts are team members."}],final:"Champion = accountable sponsor → answer **B**",whyWrong:["Incorrect — the Belt leads and performs the analysis, coached by the MBB.","","Incorrect — the Process Owner owns and sustains the process after closure.","Incorrect — the Champion is a manager who sponsors the project, not a team member."],bookRef:"Book p. 584"},{id:"sv-1-610",phase:1,topic:"1.1.6",qtype:"statements",difficulty:2,stem:`Which statements about the **Finance representative** are CORRECT?

1. Gives an independent evaluation of hard and soft savings.
2. Selects projects for the deployment.
3. Owns the control plan after handover.
4. Checks the baseline and method behind claimed savings.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:3,hint:"Finance validates the money; it does not select or own.",steps:[{title:"Check each statement",body:"1 is true: the glossary (p. 585) describes an independent evaluation of hard and/or soft savings. 4 is true: that evaluation means checking the baseline and method."},{title:"Find the false ones",body:"2 is false: the Champion selects projects. 3 is false: the Process Owner owns the control plan."}],final:"Statements 1 and 4 are correct → answer **D**",whyWrong:["Incorrect — statement 2 is false because the Champion selects projects.","Incorrect — statements 2 and 3 describe the Champion and the Process Owner.","Incorrect — statement 3 is false because the Process Owner owns the control plan.",""],bookRef:"Book p. 585"},{id:"sv-1-611",phase:1,topic:"1.1.6",qtype:"statements",difficulty:2,stem:`Which statements about the **Champion** are CORRECT?

1. Leads the day-to-day data collection.
2. Removes cross-functional barriers.
3. Selects and scopes projects in line with business priorities.
4. Gives an independent evaluation of savings.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:1,hint:"Champions select and unblock.",steps:[{title:"Check each statement",body:"2 is true: the Champion removes barriers such as budget, data access and politics. 3 is true: the Champion selects and scopes projects."},{title:"Find the false ones",body:"1 is false: data collection is team work led by the Belt. 4 is false: independent evaluation of savings is Finance's job."}],final:"Statements 2 and 3 are correct → answer **B**",whyWrong:["Incorrect — statement 1 is false because the team collects data, led by the Belt.","","Incorrect — statement 4 is false because Finance evaluates savings independently.","Incorrect — statements 1 and 4 are both false."],bookRef:"Book p. 584"},{id:"sv-1-612",phase:1,topic:"1.1.6",qtype:"statements",difficulty:2,stem:`Which statements describe Six Sigma **behaviours** that the book expects from every role?

1. Avoid changing methods once they have been learned.
2. Rely on experience rather than data when time is short.
3. Embrace change and continuous learning.
4. Share best practice and act as a role model.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:2,hint:"The book lists: tenacious, courageous, rigorous, disciplined, data-based, open to change, sharing.",steps:[{title:"Check each statement",body:"3 and 4 are true: the book (p. 228) asks every player to embrace change and continuous learning, share best practice and be a role model."},{title:"Find the false ones",body:"1 and 2 contradict the list: resisting change and replacing data with experience are the opposite of the expected behaviours."}],final:"Statements 3 and 4 are correct → answer **C**",whyWrong:["Incorrect — both statements contradict the book's call for change and data-based decisions.","Incorrect — statement 2 is false because the book asks for data-based decisions.","","Incorrect — statement 1 is false because the book asks for change and continuous learning."],bookRef:"Book p. 228"},{id:"sv-1-613",phase:1,topic:"1.1.6",qtype:"missing-word",difficulty:2,stem:`Identify the missing words in the following sentence.

The [?] is responsible for process performance and resources and is accountable for implementing the solutions.`,options:["Champion","Process Member","Process Owner","Sponsor"],answer:2,hint:"Who keeps the process working after the project?",steps:[{title:"Key idea",body:"The glossary (p. 588) says **Process Owners** are responsible for process performance and resources and accountable for implementing solutions."},{title:"Eliminate look-alikes",body:"The Champion sponsors the project; members do the work; the Sponsor sets strategy."}],final:"Process performance and resources = Process Owner → answer **C**",whyWrong:["Incorrect — the Champion is accountable for project results, not for running the process.","Incorrect — a Process Member performs activities but is not accountable for the whole process.","","Incorrect — the Executive Sponsor sets strategic direction across the programme."],bookRef:"Book p. 588"},{id:"sv-1-614",phase:1,topic:"1.1.6",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

A Black Belt leads larger projects full-time under the direction of a [?].`,options:["Champion","Green Belt","Process Member","Yellow Belt"],answer:0,hint:"Who directs and supports the Belt?",steps:[{title:"Key idea",body:"The Black Belt works full-time on projects under the direction of a **Champion**, who selects and supports the project."},{title:"Eliminate look-alikes",body:"Green and Yellow Belts are coached by the Black Belt; process members do the daily work."}],final:"Black Belt works under a Champion → answer **A**",whyWrong:["","Incorrect — Black Belts coach Green Belts, not the other way round.","Incorrect — a process member performs activities in the process and does not direct projects.","Incorrect — Yellow Belts are team members on the Black Belt's project."],bookRef:"Book p. 584"},{id:"sv-1-615",phase:1,topic:"1.1.6",qtype:"not-except",difficulty:2,stem:"Which is NOT a typical responsibility of the **Process Owner**?",options:["Providing resources and process access to the project","Implementing the solution in the process","Independently auditing the project's savings","Sustaining the gain using the control plan"],answer:2,hint:"Owner versus Finance.",steps:[{title:"Key idea",body:"The Process Owner supports projects with resources and expertise, implements solutions and sustains them after handover."},{title:"Find the outsider",body:"An **independent** evaluation of savings comes from the Finance representative — the owner is not independent of their own process."}],final:"Savings audit = Finance, not the owner → answer **C**",whyWrong:["Incorrect — giving resources and access is a normal Process Owner responsibility.","Incorrect — the owner is accountable for implementing solutions in the process.","","Incorrect — sustaining the gain with the control plan is the owner's main long-term job."],bookRef:"Book pp. 585, 588"},{id:"sv-1-616",phase:1,topic:"1.1.6",qtype:"not-except",difficulty:1,stem:"Which role does NOT normally lead a DMAIC project?",options:["Black Belt","Green Belt","Master Black Belt","Yellow Belt"],answer:3,hint:"Leaders versus team members.",steps:[{title:"Key idea",body:"Black Belts lead larger projects, Green Belts lead smaller ones, and MBBs may lead strategic projects while coaching."},{title:"Find the outsider",body:"The Yellow Belt (about 1 week of training) is a team member, not a project leader."}],final:"Yellow Belt = team member → answer **D**",whyWrong:["Incorrect — Black Belts lead larger, often cross-functional projects.","Incorrect — Green Belts lead smaller-scope projects in their own area.","Incorrect — MBBs coach Belts and can lead strategic, complex projects.",""],bookRef:"Book pp. 584–590"},{id:"sv-1-617",phase:1,topic:"1.1.6",qtype:"not-except",difficulty:3,stem:"Which is NOT a responsibility of a **Master Black Belt**?",options:["Approving and assigning projects to Belts","Coaching Belts on the use of tools","Ensuring statistical rigour in projects","Advising Champions on project selection"],answer:0,hint:"The MBB advises; who decides?",steps:[{title:"Key idea",body:"The MBB is the technical go-to expert: teaches and mentors Belts, ensures rigour and supports Champions (book p. 586)."},{title:"Find the outsider",body:"Approving and assigning projects is the **Champion's** decision; the MBB only advises."}],final:"Assigning projects = Champion → answer **A**",whyWrong:["","Incorrect — coaching Belts is the MBB's core role.","Incorrect — ensuring statistical rigour is an MBB responsibility.","Incorrect — advising Champions on project selection is an MBB responsibility."],bookRef:"Book p. 586"},{id:"sv-1-618",phase:1,topic:"1.1.6",qtype:"scenario",difficulty:3,stem:"A Black Belt claims **OMR 85,000** a year in *soft* savings from avoided overtime. Before the Champion reports it to the leadership team, who should evaluate whether the claim is valid?",options:["Master Black Belt","Process Owner","Black Belt","Finance representative"],answer:3,hint:"Soft or hard, savings need an independent check.",steps:[{title:"Key idea",body:"The Finance representative provides an independent evaluation of hard and/or soft savings (book p. 585)."},{title:"Apply to the stem",body:"Avoided overtime is a soft saving, and Finance should check the baseline and method before it is reported."},{title:"Eliminate look-alikes",body:"The MBB checks statistical rigour; the owner and Belts are not independent of the claim."}],final:"Savings check = Finance → answer **D**",whyWrong:["Incorrect — the MBB checks method and rigour, not the financial value.","Incorrect — the Process Owner benefits from the result, so the evaluation would not be independent.","Incorrect — a Black Belt leads projects; it does not validate another project's money.",""],bookRef:"Book p. 585"},{id:"sv-1-619",phase:1,topic:"1.1.6",qtype:"scenario",difficulty:3,stem:"At the Analyze tollgate, data show that the root cause of late activations lies in the credit-check step, which is **outside** the agreed scope. Who should decide whether the scope changes?",options:["Green Belt","Champion","Master Black Belt","Finance representative"],answer:1,hint:"Who owns the charter and the tollgate decision?",steps:[{title:"Key idea",body:"The Champion approves the charter, owns the scope and chairs the tollgates."},{title:"Apply to the stem",body:"Changing the scope changes the charter, so the Black Belt brings the evidence and the Champion decides."},{title:"Eliminate look-alikes",body:"The MBB advises on method; Finance reviews benefits; the Black Belt cannot change its own charter."}],final:"Scope change = Champion → answer **B**",whyWrong:["Incorrect — the Black Belt presents the evidence but cannot change the approved charter alone.","","Incorrect — the MBB may advise on the analysis but does not own the scope.","Incorrect — Finance may re-estimate benefits but does not decide the scope."],bookRef:"Book p. 584"},{id:"sv-1-620",phase:1,topic:"1.1.6",qtype:"scenario",difficulty:1,stem:"A new employee completes a **one-week** course and then helps a Black Belt map the number-porting process and collect data. Which role does she hold?",options:["Yellow Belt","Green Belt","Black Belt","Master Black Belt"],answer:0,hint:"Training length and role on the team.",steps:[{title:"Key idea",body:"The Yellow Belt trains for about 1 week and works as a team member on Belt projects."},{title:"Apply to the stem",body:"One week of training and a supporting role on a Black Belt project = Yellow Belt."}],final:"One week + team member = Yellow Belt → answer **A**",whyWrong:["","Incorrect — a Black Belt trains for about 2 weeks and leads smaller projects.","Incorrect — a Black Belt trains for about 4 weeks and leads larger projects full-time.","Incorrect — an MBB is trained beyond Black Belt and coaches other Belts."],bookRef:"Book p. 590"},{id:"sv-1-621",phase:1,topic:"1.1.6",qtype:"scenario",difficulty:1,stem:"A network engineer completes **two weeks** of training and then leads a project in her own operations area while keeping her normal job. Which role is this?",options:["Yellow Belt","Black Belt","Green Belt","Champion"],answer:2,hint:"Part-time leader of a local project.",steps:[{title:"Key idea",body:"A Black Belt trains for about 2 weeks, works part-time on improvement and leads smaller projects in their own area."},{title:"Eliminate look-alikes",body:"A Yellow Belt does not lead projects; a Black Belt is full-time; a Champion sponsors rather than leads."}],final:"Two weeks + part-time local lead = Green Belt → answer **C**",whyWrong:["Incorrect — a Yellow Belt trains for about 1 week and is a team member.","Incorrect — a Black Belt trains for about 4 weeks and works full-time on improvement.","","Incorrect — a Champion sponsors and supports projects rather than leading the DMAIC work."],bookRef:"Book p. 586"},{id:"sv-1-622",phase:1,topic:"1.1.6",qtype:"scenario",difficulty:2,stem:"The head of field operations provides technicians and data to a dispatch project and will run the improved dispatch process afterwards. She does not lead the project. Which role does she hold?",options:["Champion","Process Owner","Process Member","Green Belt"],answer:1,hint:"Resources and expertise now, accountability for the process later.",steps:[{title:"Key idea",body:"Process Owners are responsible for process performance and resources, support projects with resources and expertise, and implement the solutions (book p. 588)."},{title:"Apply to the stem",body:"She gives resources now and will run the new process: Process Owner."},{title:"Eliminate look-alikes",body:"A Champion sponsors the project, members do the work, the Black Belt leads it."}],final:"Provides resources and runs the process = Process Owner → answer **B**",whyWrong:["Incorrect — the Champion sponsors the project and is accountable for its results, not for running dispatch.","","Incorrect — a Process Member performs activities but is not responsible for the whole process.","Incorrect — the stem says she does not lead the project, which is the Belt's role."],bookRef:"Book p. 588"},{id:"sv-1-623",phase:1,topic:"1.1.6",qtype:"best-action",difficulty:3,stem:"After a successful pilot, a Black Belt closed the project herself and reported the savings to the leadership team without involving Finance. Was this an appropriate action?",options:["Yes, because the Belt is accountable for the project's savings","Yes, because Finance reviews only Black Belt projects","No, because only the Master Black Belt may report savings to leadership","No, because the Champion, Belt and Finance should agree the project is complete"],answer:3,hint:"Recall the book's Control checklist for closure.",steps:[{title:"Key idea",body:"The book's Control checklist (p. 578) asks whether the Champion, the Belt and Finance all agree the project is complete."},{title:"Apply to the stem",body:"Closing alone, with unvalidated savings, skips both the Champion and Finance."},{title:"Eliminate look-alikes",body:"The Champion is accountable for results; Finance reviews all projects; the MBB does not own reporting."}],final:"Closure needs Champion, Belt and Finance → answer **D**",whyWrong:["Incorrect — the Champion is accountable for results, and savings need independent evaluation by Finance.","Incorrect — Finance evaluates savings for projects of any belt level.","Incorrect — the MBB coaches on method; it is not the only role allowed to report savings.",""],bookRef:"Book p. 578"},{id:"sv-1-624",phase:1,topic:"1.1.6",qtype:"best-action",difficulty:3,stem:"To make sure the gains of a churn-reduction project last, the Champion asks the Black Belt to take permanent ownership of the retention process after closure. Was this an appropriate action?",options:["Yes, because the Belt knows the new solution best","Yes, because Belts own the processes they improve","No, because sustaining belongs to the Process Owner who runs the process long term","No, because the Champion should own the retention process personally"],answer:2,hint:"Who keeps the gain after the project?",steps:[{title:"Key idea",body:"A Belt leads a project for a few months; the Process Owner runs the process for years and receives the control plan (book p. 578)."},{title:"Apply to the stem",body:"Handing permanent ownership to a part-time Green Belt leaves the real owner uncommitted, so the gain is likely to fade."},{title:"Eliminate look-alikes",body:"Belts do not own processes, and the Champion sponsors projects rather than running processes."}],final:"Sustain = Process Owner → answer **C**",whyWrong:["Incorrect — knowing the solution does not make the Belt accountable for process performance.","Incorrect — Belts lead projects; ownership stays with the Process Owner.","","Incorrect — the Champion sponsors projects; day-to-day ownership belongs to the Process Owner."],bookRef:"Book pp. 578, 588"},{id:"sv-1-625",phase:1,topic:"1.1.6",qtype:"best-action",difficulty:3,stem:"A Black Belt suspects that the scope of her new project is too large for a part-time leader. What is the BEST action?",options:["Widen the scope further so the savings justify the effort","Ask Finance to lower the savings target in the charter","Start Measure now and decide about the scope later","Review the scope with the Champion, with advice from a Master Black Belt"],answer:3,hint:"Who owns the scope, and who can advise on it?",steps:[{title:"Key idea",body:"The Champion scopes and approves projects; the MBB advises on project selection and scope."},{title:"Apply to the stem",body:"Green Belts lead smaller-scope projects, so an over-large scope should be raised with the Champion early."},{title:"Eliminate look-alikes",body:"Widening makes it worse; Finance validates savings, not scope; delaying the decision wastes effort."}],final:"Raise scope with the Champion early → answer **D**",whyWrong:["Incorrect — a wider scope makes the project even less suitable for a part-time Green Belt.","Incorrect — Finance evaluates savings; the scope belongs to the Champion.","Incorrect — starting Measure on a poor scope wastes data collection effort.",""],bookRef:"Book pp. 584, 586"},{id:"sv-1-626",phase:1,topic:"1.1.6",qtype:"best-action",difficulty:2,stem:"A newly appointed Champion must launch improvement projects in customer care. What should she do FIRST?",options:["Assign Yellow Belts to start collecting data","Write the control plans for each project","Identify problem areas that match business priorities","Ask Finance to sign off the final savings"],answer:2,hint:"The first step on the book's DMAIC roadmap.",steps:[{title:"Key idea",body:"The book's roadmap (p. 230) starts with **identify problem area**, owned by the Champion or Process Owner."},{title:"Apply to the stem",body:"Before any team, data or plans, the Champion picks problem areas aligned with business priorities."},{title:"Eliminate look-alikes",body:"Data collection, control plans and final savings all come much later."}],final:"First: identify the problem area → answer **C**",whyWrong:["Incorrect — data collection follows a defined, chartered project.","Incorrect — control plans are written in the Control phase.","","Incorrect — final savings are validated at closure, not at launch."],bookRef:"Book p. 230"},{id:"sv-1-627",phase:1,topic:"1.1.6",qtype:"output",difficulty:1,stem:`A project file lists who owns each task:

\`\`\`
Project roles - Repeat-visit reduction
Task                          Role
Approve charter and scope     ?
Lead DMAIC and apply tools    Green Belt
Validate hard savings         Finance representative
Sustain the control plan      Process Owner
\`\`\`

Which role belongs in the blank?`,options:["Champion","Master Black Belt","Yellow Belt","Process Member"],answer:0,hint:"Who approves the charter?",steps:[{title:"Read the table",body:"Leading, validating and sustaining are already assigned. The missing task is approving the charter and scope."},{title:"Decide",body:"The Champion selects and scopes projects and approves the charter."}],final:"Charter approval = Champion → answer **A**",whyWrong:["","Incorrect — the MBB advises on scope and method but does not approve the charter.","Incorrect — a Yellow Belt is a team member without authority over the charter.","Incorrect — a process member performs activities in the process and does not approve projects."],bookRef:"Book p. 584"},{id:"sv-1-628",phase:1,topic:"1.1.6",qtype:"output",difficulty:3,stem:`A tollgate log for a billing-dispute project shows:

\`\`\`
Tollgate review - Analyze      Project: Billing disputes
Item                       Status   Note
Root cause verified        Yes      p = 0.003
Savings estimate           Draft    Not yet reviewed by Finance
Process Owner sign-up      No       Owner not attending reviews
\`\`\`

Which risk to **sustaining** the improvement does the log show?`,options:["The root cause is not proven because p is below 0.05","The gain may fade because the Process Owner is not engaged","The savings cannot be sustained until Finance leads the project","The Champion must take over the process after closure"],answer:1,hint:"Who keeps the gain after the Belt leaves?",steps:[{title:"Read the log",body:"The root cause is verified (p = 0.003). Savings are in draft. The Process Owner has not signed up and is not attending."},{title:"Decide",body:"The owner receives the control plan and sustains the gain, so an absent owner is the sustainment risk."},{title:"Eliminate look-alikes",body:"p < 0.05 supports the root cause; Finance validates rather than leads; the Champion does not run the process."}],final:"No owner commitment = sustainment risk → answer **B**",whyWrong:["Incorrect — p = 0.003 is below 0.05, which supports the root cause.","","Incorrect — Finance evaluates savings; it does not lead the project or sustain the process.","Incorrect — the Process Owner, not the Champion, runs the process after closure."],bookRef:"Book pp. 578, 588"},{id:"sv-1-629",phase:1,topic:"1.1.6",qtype:"true-false",difficulty:2,stem:"The Master Black Belt, rather than the Champion, is the role that selects and assigns projects to Belts. True or False?",options:["True","False"],answer:1,hint:"Advising versus deciding.",steps:[{title:"Key idea",body:"The Champion recognises, defines, assigns and supports projects (book p. 584). The MBB advises Champions."},{title:"Apply to the stem",body:"The statement gives the Champion's decision to the MBB, so it is false."}],final:"Champion selects; MBB advises → False → answer **B**",whyWrong:["Incorrect — selecting and assigning projects is the Champion's role; the MBB only advises.",""],bookRef:"Book pp. 584, 586"},{id:"sv-1-630",phase:1,topic:"1.1.6",qtype:"sequence",difficulty:2,stem:`Put these events in the usual order across a project's life.

- **P** Champion, Belt and Finance agree the project is complete
- **Q** Champion selects and scopes the project
- **R** Green Belt leads DMAIC with the team
- **S** Process Owner receives the control plan`,options:["Q, R, P, S","R, Q, S, P","Q, S, R, P","Q, R, S, P"],answer:3,hint:"Select → lead → hand over → close.",steps:[{title:"Key idea",body:"The Champion selects the project, the Belt leads it, the control plan is handed to the owner, and then closure is agreed (book p. 578)."},{title:"Apply to the stem",body:"Q → R → S → P."}],final:"Q, R, S, P → answer **D**",whyWrong:["Incorrect — the control plan is handed over before the parties agree the project is complete.","Incorrect — the Belt cannot lead DMAIC before the Champion has selected the project.","Incorrect — the control plan comes out of the DMAIC work, so it cannot be handed over first.",""],bookRef:"Book pp. 230, 578"},{id:"sv-1-631",phase:1,topic:"1.1.6",qtype:"sequence",difficulty:1,stem:`Order these roles from **least** to **most** training.

- **P** Black Belt
- **Q** Green Belt
- **R** Master Black Belt
- **S** Yellow Belt`,options:["S, Q, P, R","S, P, Q, R","Q, S, P, R","S, Q, R, P"],answer:0,hint:"About 1 week, 2 weeks, 4 weeks, then beyond.",steps:[{title:"Key idea",body:"Yellow Belt about 1 week, Green Belt about 2 weeks, Black Belt about 4 weeks, Master Black Belt beyond Black Belt."},{title:"Apply to the stem",body:"S → Q → P → R."}],final:"S, Q, P, R → answer **A**",whyWrong:["","Incorrect — the Black Belt (about 2 weeks) trains less than the Black Belt (about 4 weeks).","Incorrect — the Yellow Belt (about 1 week) trains less than the Black Belt.","Incorrect — the Master Black Belt is trained beyond the Black Belt."],bookRef:"Book pp. 584–590"},{id:"sv-1-632",phase:1,topic:"1.2.1",qtype:"concept",difficulty:1,stem:"In the book's preferred description of a process, what does the **process map** show?",options:["The reporting lines of the departments involved","The budget allocated to each step","The workflow of the process, step by step","The verified root causes of the defects"],answer:2,hint:"Name it, draw its flow, explain its purpose.",steps:[{title:"Key idea",body:"The book (p. 99) describes a process with a generic name, a **process map showing the workflow**, and an operational description."},{title:"Eliminate look-alikes",body:"Reporting lines belong on an organisation chart, budgets in finance plans, and verified root causes come from Analyze."}],final:"Process map = the workflow → answer **C**",whyWrong:["Incorrect — reporting lines are shown on an organisation chart; a process is not a department.","Incorrect — budgets are management data, not part of a process map.","","Incorrect — root causes are verified with data in Analyze, not drawn on the Define map."],bookRef:"Book p. 99"},{id:"sv-1-633",phase:1,topic:"1.2.1",qtype:"concept",difficulty:1,stem:"According to the book, who is the main audience for a **Level 2** process map?",options:["Senior managers agreeing the scope","The improvement team analysing yields and DPU","External customers choosing a product","The workers who perform the steps"],answer:3,hint:"Road-map levels: world, country, city — each for a different reader.",steps:[{title:"Key idea",body:"The book (p. 102) gives three levels: Level 1 macro map for management, Level 2 process map for workers, Level 3 micro map for improvement."},{title:"Apply to the stem",body:"Level 2 shows the steps as the performers do them, so its audience is the workers."},{title:"Eliminate look-alikes",body:"Management uses Level 1; yields, DPU and RTY belong on Level 3."}],final:"Level 2 = workers → answer **D**",whyWrong:["Incorrect — senior managers use the Level 1 macro map with a few major steps.","Incorrect — yields, DPU and RTY are shown on the Level 3 micro map for improvement work.","Incorrect — process maps are internal views; the book does not name customers as a map audience.",""],bookRef:"Book p. 102"},{id:"sv-1-634",phase:1,topic:"1.2.1",qtype:"concept",difficulty:2,stem:"Which statement about showing a **macro (Level 1)** map to management in Define is CORRECT?",options:["It gives managers the cycle time and yield of every micro step","It shows the scope of the project so managers can adjust their expectations","It replaces the project charter as the record of the problem and goal","It proves which inputs cause the defect in the output"],answer:1,hint:"What does the book say a macro map tells management?",steps:[{title:"Key idea",body:`The book (p. 108) says the macro map also shows management the project's scope "so they can adjust their expectations".`},{title:"Eliminate look-alikes",body:"Step data belong on Level 3; the charter is a separate document; proof of causes comes in Analyze."}],final:"Macro map = shared view of scope → answer **B**",whyWrong:["Incorrect — cycle times and yields per step belong on the Level 3 micro map.","","Incorrect — the charter records problem, goal, scope and team; the map supports it but does not replace it.","Incorrect — a map shows flow; causes are verified with data in Analyze."],bookRef:"Book p. 108"},{id:"sv-1-635",phase:1,topic:"1.2.1",qtype:"statements",difficulty:2,stem:`Which statements describe a **process** in Lean Six Sigma terms?

1. The HR department as drawn on the organisation chart.
2. A one-time move of the head office to a new building.
3. Billing turning monthly usage records into invoices.
4. The service desk turning logged incidents into restored services.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:2,hint:"A process repeats and transforms inputs into outputs.",steps:[{title:"Check each statement",body:"3 and 4 are true: each repeats and transforms inputs (usage records, incidents) into outputs (invoices, restored services) — book p. 587."},{title:"Find the false ones",body:"1 is false: a department groups people; it is not a flow of work. 2 is false: a one-time move is a project, not a repeatable process."}],final:"Statements 3 and 4 are correct → answer **C**",whyWrong:["Incorrect — a department is not a process, and a one-time move is a project.","Incorrect — statement 2 is false because a one-off event is a project, not a process.","","Incorrect — statement 1 is false because a department groups people rather than describing a flow of work."],bookRef:"Book p. 587"},{id:"sv-1-636",phase:1,topic:"1.2.1",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

The book compares process map levels with road maps: a Level 3 micro map is like a [?] map.`,options:["city","country","region","world"],answer:0,hint:"World → country → city, from least to most detail.",steps:[{title:"Key idea",body:"The book (p. 102) compares the levels with road maps: world (Level 1), country (Level 2), city (Level 3)."},{title:"Apply to the stem",body:"The micro map is the most detailed, like a city map."}],final:"Level 3 = city map → answer **A**",whyWrong:["","Incorrect — the country view matches Level 2, the worker's process map.","Incorrect — 'region' is not one of the book's three road-map levels.","Incorrect — the world view matches the Level 1 macro map."],bookRef:"Book p. 102"},{id:"sv-1-637",phase:1,topic:"1.2.1",qtype:"not-except",difficulty:2,stem:"When a process is first described at Level 1 in Define, which question is NOT normally answered?",options:["What is the process called?","What are the yield and cycle time of each micro step?","Where does the process start and stop?","Who owns the process end to end?"],answer:1,hint:"Define stays at a high level.",steps:[{title:"Key idea",body:"In Define the process gets a name, boundaries (start and stop triggers), major steps and an owner."},{title:"Find the outsider",body:"Yield and cycle time per micro step are Level 3 data gathered later, in Measure."}],final:"Micro-step data come later → answer **B**",whyWrong:["Incorrect — naming the process is part of the Level 1 description.","","Incorrect — start and stop triggers set the boundary in Define.","Incorrect — naming one process owner is part of defining the process."],bookRef:"Book pp. 102, 108"},{id:"sv-1-638",phase:1,topic:"1.2.1",qtype:"scenario",difficulty:2,stem:"While defining an order process, a team finds that provisioning spends two hours each week producing an order-status spreadsheet. Nobody in sales, billing or management opens or uses it. What does this suggest?",options:["The activity has no customer, so it is a candidate for removal","The spreadsheet is a key output and needs a specification","The spreadsheet is a noise input that cannot be controlled","The activity should be moved to the Level 1 macro map"],answer:0,hint:"A process exists to deliver an output to someone.",steps:[{title:"Key idea",body:"A process transforms inputs into outputs **for a customer**. If nobody receives or uses the output, the activity adds no value."},{title:"Apply to the stem",body:"No one uses the spreadsheet, so the activity is a candidate for removal."},{title:"Eliminate look-alikes",body:"A specification is needed only if someone uses the output; it is an output, not an input; map level does not fix it."}],final:"No customer → candidate for removal → answer **A**",whyWrong:["","Incorrect — a specification is negotiated with a customer, and this output has none.","Incorrect — the spreadsheet is something the process produces, not an input to it.","Incorrect — the Level 1 map shows only major steps; moving the activity there does not add value."],bookRef:"Book pp. 99, 587"},{id:"sv-1-639",phase:1,topic:"1.2.1",qtype:"output",difficulty:3,stem:`A team reviews three maps of the same process before its Define tollgate:

\`\`\`
Map review - Restore customer service
Map   Boxes   Content
M1        5   Major steps only, no data
M2       18   Steps as agents perform them
M3       31   Steps with yield, DPU, RTY and VA/NVA tags
\`\`\`

Which map should the team use to agree the project scope with the Champion at the tollgate?`,options:["M2, because the Champion needs to see every agent action","M3, because scope must be agreed using yield and DPU data","M1, because Define works at the macro level for management","All three together, because scope needs every level of detail"],answer:2,hint:"Match the map level to the audience and the phase.",steps:[{title:"Read the table",body:"M1 = Level 1 (macro), M2 = Level 2 (worker), M3 = Level 3 (micro)."},{title:"Decide",body:"Define works at Level 1, and the macro map shows management the scope (book p. 108)."},{title:"Eliminate look-alikes",body:"Worker-level and micro-level detail come later, in Measure."}],final:"Define + management = Level 1 → M1 → answer **C**",whyWrong:["Incorrect — the Level 2 map is for workers; a Champion agreeing scope needs the macro view.","Incorrect — yield, DPU and VA/NVA data belong to Level 3 work in Measure.","","Incorrect — showing every level hides the scope in detail; Define works at Level 1."],bookRef:"Book pp. 102, 108"},{id:"sv-1-640",phase:1,topic:"1.2.1",qtype:"true-false",difficulty:1,stem:"According to the book, each step in a process should add value as the customer sees it. True or False?",options:["True","False"],answer:0,hint:"The book describes a process as a blending of inputs into a desired output.",steps:[{title:"Key idea",body:"The book (p. 99) says a process blends inputs to produce a desired output, and each step should **add value as the customer sees it**."},{title:"Apply to the stem",body:"The statement matches the book, so it is true."}],final:"Steps should add customer value → True → answer **A**",whyWrong:["","Incorrect — the book does say each step should add value in the customer's eyes."],bookRef:"Book p. 99"}];export{e as items};
